import{J as s}from"./G4ib9BhL.js";const r={"signals.0.label":"лет в промышленной разработке","signals.0.note":"От стажировки на React до senior-ответственности в международных продуктовых командах.","signals.1.label":"пользователей","signals.1.note":"Продакшн-интерфейсы, работающие на значимом для бизнеса масштабе.","signals.2.label":"проектов сдано","signals.2.note":"Веб, мобильные и данные-интенсивные платформы.","signals.3.label":"проектов оптимизировано","signals.3.note":"Улучшения производительности, архитектуры и поддерживаемости.","case_studies.01.kicker":"Архитектура на масштабе продукта","case_studies.01.title":"Сделать десять модулей одной системой.","case_studies.01.problem":"Растущей поверхности продукта на Vue нужно было оставаться согласованной, пока 10+ модулей развивались параллельно для платформы с более чем миллионом пользователей в год.","case_studies.01.solution":"Определил переиспользуемые паттерны Vue 3 / TypeScript вокруг composition, роутинга, состояния и общих продуктовых сценариев, чтобы новые фичи стартовали от готовой системы, а не локальных договорённостей.","case_studies.01.result":"Архитектура сократила время реализации фич примерно на 30% и заложила более прочную базу для разработки между модулями.","case_studies.01.metrics.0.label":"продуктовых модулей","case_studies.01.metrics.1.label":"быстрее доставка фич","case_studies.02.kicker":"Производительность как архитектура","case_studies.02.title":"Относиться ко времени загрузки как к графу, а не числу.","case_studies.02.problem":"Высоконагруженные экраны замедлялись из-за работы, распределённой между рендерингом, получением данных, кэшированием и асинхронными UI-потоками, а не из-за одного очевидного узкого места.","case_studies.02.solution":"Оптимизировал весь путь от запроса до рендера: поведение рендеринга, кэширование, асинхронную оркестрацию и паттерны API-запросов, подкрепив работу Core Web Vitals, Lighthouse, тестами и мониторингом Sentry.","case_studies.02.result":"Среднее время загрузки страницы снизилось примерно с 3.2 до 2.1 секунды, пока платформа продолжала развиваться.","case_studies.02.metrics.0.label":"средняя загрузка страницы","case_studies.02.metrics.1.label":"примерное снижение","case_studies.03.kicker":"Производительность геоданных","case_studies.03.title":"Полмиллиона объектов на карте должны оставаться интерактивными.","case_studies.03.problem":"Плотным GIS-интерфейсам нужно было рендерить и обрабатывать наборы данных из примерно 300–500 тыс. геопространственных объектов, не делая первое взаимодействие ощутимо медленным.","case_studies.03.solution":"Перестроил слои и стили, внедрил кластеризацию и фильтрацию на клиенте, а также сократил лишнюю работу на пути данных Vuex–Elasticsearch.","case_studies.03.result":"Начальный рендеринг Mapbox GL JS упал примерно с 800 до 480 мс, плюс отдельная работа над алгоритмами дала 30%-ное улучшение скорости геопоиска.","case_studies.03.metrics.0.label":"начальный рендер карты","case_studies.03.metrics.1.label":"геопространственных объектов","case_studies.04.kicker":"Переиспользуемые системы доставки","case_studies.04.title":"Собирать следующий региональный продукт из конфигурации, а не копированием.","case_studies.04.problem":"Десятки региональных GIS-продуктов повторяли одни и те же UI- и данные-паттерны, но повторная реализация замедляла доставку и удорожала консистентность.","case_studies.04.solution":"Создал централизованную архитектуру со 100+ переиспользуемыми Vue-компонентами и общими модулями, затем стандартизировал BEM, теминг, ролевые паттерны, линтинг и практики тестирования вокруг неё.","case_studies.04.result":"Похожая реализация стала занимать до 50% меньше времени; некоторые запуски, ранее занимавшие около месяца, стали укладываться примерно в неделю.","case_studies.04.metrics.0.label":"переиспользуемых компонентов","case_studies.04.metrics.1.label":"похожих реализаций","surfaces.A.title":"Высоконагруженные продуктовые модули","surfaces.A.text":"Интерфейсы, где архитектура, кэширование, состояние и поведение API должны работать как единая продуктовая система.","surfaces.B.title":"Геопространственные системы","surfaces.B.text":"Продукты с большим количеством карт, где объём данных меняет саму фронтенд-архитектуру, а не только слой рендеринга.","surfaces.C.title":"Программы модернизации","surfaces.C.text":"Переход с legacy на современный стек, который не останавливает доставку продукта, пока меняется техническая основа.","surfaces.D.title":"End-to-end доставка продукта","surfaces.D.text":"Фронтенд-инженерия с достаточной глубиной бэкенда, чтобы владеть API, границами интеграций и поведением в production.","principles.01.title":"Сначала измерить, потом переписывать.","principles.01.text":"Изменение производительности должно начинаться с фактов и заканчиваться результатом, заметным пользователю.","principles.02.title":"Архитектура — это инструмент доставки.","principles.02.text":"Лучшая абстракция — та, что делает следующую фичу дешевле, безопаснее и понятнее.","principles.03.title":"Фронтенд — часть системы.","principles.03.text":"Рендеринг, форма данных, API, доступность, наблюдаемость и релизные пайплайны — одна инженерная поверхность.","principles.04.title":"Senior — значит снижать неопределённость.","principles.04.text":"Техническое лидерство — это делать компромиссы видимыми, чтобы команда двигалась быстро, не накапливая скрытых рисков.","milestones.ciklum.role":"Senior Software Engineer","milestones.ciklum.focus":"Фронтенд-архитектура · модернизация продукта · производительность · техническое лидерство","milestones.keyhorse.role":"Middle → Senior → Team Lead Software Engineer","milestones.keyhorse.focus":"GIS · цифровые двойники · инженерное лидерство · переиспользуемые системы · backend API","milestones.dar.role":"Junior Software Engineer","milestones.dar.focus":"Высокообъёмная веб-разработка · e-commerce · мобильные приложения · производительность","milestones.epam.role":"Software Engineer Intern","milestones.epam.focus":"React · TypeScript · переиспользуемый UI · инженерные основы","milestones.freelance.role":"Freelance Software Engineer","milestones.freelance.focus":"Фриланс-разработка на Vue/React · полный цикл доставки SaaS и e-commerce · работа с клиентами","milestones.ciklum.location":"Бухарест, Румыния (удалённо)","milestones.ciklum.summary":"Глобальный лидер в области цифровых продуктов и трансформации корпоративного ПО, базирующийся в Великобритании.","milestones.ciklum.highlight_0.label":"Архитектура","milestones.ciklum.highlight_0.text":"Выстроил единую архитектуру на Vue 3/строгом TypeScript — переиспользуемую библиотеку компонентов и типобезопасный REST/GraphQL API-слой — для 10+ модулей (1–3 млн пользователей), соответствующую стандарту WCAG AA, сократив время реализации фич примерно на 30%.","milestones.ciklum.highlight_1.label":"Техническое лидерство","milestones.ciklum.highlight_1.text":"Принимал архитектурные решения на фронтенде, вёл планирование спринтов и проработку бэклога для команды из 6 инженеров; проводил ~15 ревью merge-реквестов в GitLab в неделю, снизив количество дефектов после мержа на 35%.","milestones.ciklum.highlight_2.label":"Производительность и Core Web Vitals","milestones.ciklum.highlight_2.text":"Оптимизировал рендеринг, кэширование и паттерны сетевых запросов в высоконагруженных модулях, снизив задержку взаимодействия (INP) примерно с 280 мс до 150 мс и сократив количество дублирующихся API-запросов на 40%.","milestones.ciklum.highlight_3.label":"Модернизация и надёжность","milestones.ciklum.highlight_3.text":"Модернизировал legacy-кодовую базу на Vue 2 до Vue 3, Composition API, Pinia и Vite, уменьшив размер бандла на 20%; повысил надёжность за счёт тестирования на Vitest/Jest, мониторинга в Sentry и CI/CD-процессов.","milestones.ciklum.highlight_4.label":"Инструменты, мобильная разработка и AI","milestones.ciklum.highlight_4.text":"Структурировал кодовую базу по Feature-Sliced Design с использованием TanStack Query, сократив объём шаблонного кода на ~25%; расширил дизайн-систему на мобильное приложение на Ionic/Capacitor и внедрил AI-инструменты для разработки (Cursor, Claude Code).","milestones.keyhorse.location":"Алматы, Казахстан","milestones.keyhorse.summary":"Компания GIS- и digital-twin-платформ, работающая в Центральной Азии.","milestones.keyhorse.roles.team-lead.label":"Team Lead","milestones.keyhorse.roles.team-lead.highlight_0.label":"Инженерное лидерство","milestones.keyhorse.roles.team-lead.highlight_0.text":"Руководил инженерным департаментом из 18 разработчиков в составе 3 подкоманд, возглавил переход на Scrum и определял техническое направление для реализации 80+ крупных региональных и 100+ более мелких digital-twin проектов для 1,5 млн+ активных пользователей в 4 странах.","milestones.keyhorse.roles.team-lead.highlight_1.label":"Самостоятельная доставка продуктов","milestones.keyhorse.roles.team-lead.highlight_1.text":"Самостоятельно спроектировал и запустил 10 корпоративных платформ с нуля за 1–1,5 месяца каждую, сократив time-to-market примерно в 2 раза по сравнению со средним историческим показателем компании.","milestones.keyhorse.roles.team-lead.highlight_2.label":"Процессы и управление","milestones.keyhorse.roles.team-lead.highlight_2.text":"Вёл планирование спринтов, оценку задач и техническую документацию, проводил ~50 код-ревью в неделю и внедрил стандарты документации, сократившие время адаптации новых сотрудников на 40%.","milestones.keyhorse.roles.mid-senior.label":"Middle → Senior","milestones.keyhorse.roles.mid-senior.highlight_0.label":"Производительность геосервисов","milestones.keyhorse.roles.mid-senior.highlight_0.text":"Снизил время рендеринга Mapbox GL JS на 40% (с 800 мс до 480 мс) и перестроил паттерны индексации/запросов в Elasticsearch с мемоизированными Vuex-геттерами, сократив задержку поиска на 30% на датасетах из 500 тыс.+ гео-объектов.","milestones.keyhorse.roles.mid-senior.highlight_1.label":"Фронтенд-архитектура","milestones.keyhorse.roles.mid-senior.highlight_1.text":"Спроектировал единую Vue-архитектуру (100+ FSD-компонентов), задокументированную в общей библиотеке компонентов Storybook для стандартизации UI-паттернов между командами, сократив цикл разработки фич на 50%.","milestones.keyhorse.roles.mid-senior.highlight_2.label":"Backend и проектирование данных","milestones.keyhorse.roles.mid-senior.highlight_2.text":"Разработал 35+ REST-эндпоинтов на Django/PostgreSQL с кэшированием на Redis и оптимизированными хранимыми процедурами PL/pgSQL для крупных геопространственных датасетов, поддерживая 99,9% продакшн-аптайма при генерации типобезопасных API-клиентов для фронтенд-интеграции.","milestones.keyhorse.roles.mid-senior.highlight_3.label":"DevOps и автоматизация","milestones.keyhorse.roles.mid-senior.highlight_3.text":"Спроектировал стратегию тестирования на Vitest, Playwright и Cypress и внедрил production quality gates через единые GitLab CI/CD пайплайны для 86 репозиториев, подняв покрытие кода до 70–80% и снизив число регрессионных багов на 30%.","milestones.keyhorse.roles.mid-senior.highlight_4.label":"Дизайн-системы и WCAG","milestones.keyhorse.roles.mid-senior.highlight_4.text":"Разработал CSS-фреймворк на основе дизайн-токенов, SCSS и методологии BEM в соответствии со стандартом WCAG AA, сократив время реализации UI с ~3 дней до ~4 часов.","milestones.dar.summary":"Технологическая группа, разрабатывающая цифровые продукты и платформы в сферах финтеха, образования, спорта и бизнес-операций.","milestones.dar.highlight_0.label":"Архитектура продакшн-приложений","milestones.dar.highlight_0.text":"Поставил 30+ многостраничных production-приложений (8+ страниц каждое), одновременно ведя до 3–4 параллельных проектов, сократив время доставки на 25% (5–10 дней на цикл) за счёт переиспользуемой библиотеки компонентов Vue/React (34 компонента, архитектура BEM).","milestones.dar.highlight_1.label":"Доставка платформ","milestones.dar.highlight_1.text":"Самостоятельно спроектировал и запустил две полноценные платформы — доставку еды и бронирование жилья — примерно за 1 месяц каждую, включая анимации на GSAP, для 150–200 ресторанов в 3 городах и 100–150 объектов недвижимости.","milestones.dar.highlight_2.label":"Производительность и SEO","milestones.dar.highlight_2.text":"Сократил время загрузки страниц на 40% (до 1,8–2,2 с) за счёт SSR, code splitting, ленивой загрузки и оптимизации бандла, достигнув 100/100 по SEO в Lighthouse на большинстве проектов.","milestones.dar.highlight_3.label":"Кросс-платформенная разработка","milestones.dar.highlight_3.text":"Выпустил 5–7 production мобильных приложений (iOS/Android) на Ionic, Capacitor и React Native с переиспользованием 40–50% кода между платформами.","milestones.dar.highlight_4.label":"Backend и API","milestones.dar.highlight_4.text":"Разработал и поддерживал REST-бэкенды на Laravel/MySQL — проектирование API, схема БД и аутентификация — для 6 из этих приложений, обрабатывающих 15 тыс.+ запросов в день.","milestones.epam.summary":"Глобальная IT-консалтинговая и digital-engineering компания.","milestones.epam.highlight_0.label":"Конкурсный отбор","milestones.epam.highlight_0.text":"Был отобран 1 из 3 инженеров среди 40+ кандидатов в рамках конкурсного технического отбора.","milestones.epam.highlight_1.label":"Фронтенд-разработка","milestones.epam.highlight_1.text":"Разрабатывал адаптивные интерфейсы на React/TypeScript и переиспользуемые библиотеки компонентов, интегрируя API в production-процессы; внёс вклад в 5+ корпоративных внутренних инструментов.","milestones.epam.highlight_2.label":"Профессиональный рост","milestones.epam.highlight_2.text":"Участвовал в код-ревью корпоративного уровня, unit-тестировании и стандартах доставки — основа, которая легла в основу всех последующих ролей.","milestones.freelance.location":"Удалённо (международные клиенты)","milestones.freelance.summary":"Независимая фриланс- и контрактная работа с международными клиентами, велась параллельно с основной занятостью.","milestones.freelance.highlight_0.label":"Доставка проектов клиентам","milestones.freelance.highlight_0.text":"Реализовал 40+ международных проектов на Vue/React (SaaS, e-commerce) со 100% соблюдением сроков и рейтингом 5.0, полностью отвечая за SDLC от обсуждения с клиентом до продакшена, включая интеграцию сложных сторонних API.","proof_items.0.label":"Образование","proof_items.0.value":"Информационные системы","proof_items.0.note":"Suleyman Demirel University · 2018–2022 · GPA 3.72 / 4.0","proof_items.1.label":"Английский","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"Академический IELTS · результат CEFR C1","proof_items.2.label":"Признание","proof_items.2.value":"Серебряная медаль","proof_items.2.note":"Infomatrix Asia-Pacific 2018 — международный конкурс компьютерных проектов.","proof_items.3.label":"Рекомендация","proof_items.3.value":"KeyHorse","proof_items.3.note":"Подписанная рекомендация от руководства компании","proof_items.4.label":"Языки","proof_items.4.value":"5 языков","proof_items.4.note":"Английский — свободное рабочее владение · Казахский и русский — родные · Турецкий — разговорный уровень · Китайский — базовый уровень","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"Результат академического IELTS (CEFR C1) — подтверждение свободного профессионального английского для международных, remote-first инженерных ролей.","proof_documents.chinese-proficiency.title":"Владение китайским языком","proof_documents.chinese-proficiency.description":"Базовый уровень китайского языка, развитый параллельно с профессиональной работой с трансграничными продуктовыми и бизнес-командами.","proof_documents.infomatrix.title":"Серебряная медаль — Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"Признание на международном конкурсе компьютерных проектов за одну из ранних инженерных работ.","proof_documents.keyhorse.title":"Рекомендательное письмо — KeyHorse","proof_documents.keyhorse.description":"Подписанная рекомендация на бланке KeyHorse, рекомендующая Жасулана на инженерную позицию senior-уровня.","projects.geonomix.description":"Масштабная геопространственная платформа и цифровой двойник, объединяющая интерактивные карты, муниципальные данные, цифровые реестры, госуслуги и инструменты мониторинга в региональных внедрениях.","projects.midas-event.description":"Сайт event-агентства, построенный как просматриваемое портфолио прошедших мероприятий, а не статичный список услуг, с интерактивными деталями на React.","projects.kostyum.description":"Адаптивный фронтенд e-commerce для мужской моды с переиспользуемым UI каталога товаров и упором на плавный опыт покупок на десктопе и мобильных.","projects.unistory.description":"Интерфейс цифрового продукта, интегрирующий состояние крипто-кошелька и асинхронные данные бэкенда в переиспользуемые продуктовые компоненты на React.","projects.kazmed.description":"Корпоративный фронтенд для авторизованного партнёра по обслуживанию медицинского оборудования, построенный вокруг каталога на Swiper вместо длинных текстовых страниц.","projects.dostyk-trans-terminal.description":"Корпоративный сайт логистического терминала на переходе Достык–Алашанькоу, представляющий услуги обработки, хранения и перевалки контейнеров.","projects.melissa.description":"Крупная онлайн-аптека с 13 000+ товаров, включая навигацию по каталогу, поиск, фильтрацию, сортировку, страницы товаров, корзину и интеграции с бэкендом.","projects.abi-construction.description":"Сайт строительной компании, сочетающий CMS-бэкенд на WordPress с интерактивными галереями проектов на Vue.","projects.tahit.description":"Фронтенд производственной компании, демонстрирующий возможности текстильного производства, технологии, продукцию и услуги на десктопе и мобильных.","projects.dobraya.description":"Витрина онлайн-аптеки с адаптивными каталогами, навигацией по категориям, поиском, фильтрацией и сценариями оформления заказа.","projects.asia-mebel.description":"Коммерческий каталог мебельных материалов, фурнитуры, инструментов и услуг со структурированной навигацией, фильтрацией, поиском и страницами товаров.","projects.pharmacom.description":"Сайт для сети прививочных клиник и аптек, организованный вокруг локаций, услуг и информации для пациентов, а не одной статичной главной страницы.","projects.navat.description":"Промо-лендинг ресторана с адаптивным визуальным опытом, выстроенным вокруг меню, атмосферы и бренда.","projects.asia-credit-bank.description":"Сайт контакт-центра банка, превращающий большой набор страниц с продуктами и поддержкой в быструю, удобную для навигации структуру.","projects.geonomix.note":"Продукт, где карта — главное, а объём данных и переиспользуемая региональная доставка определили фронтенд-архитектуру.","projects.melissa.note":"Опыт крупного каталога, где информационная архитектура важна не меньше, чем полировка интерфейса."},a={"signals.0.label":"жыл өндірістік тәжірибе","signals.0.note":"React тәжірибешісінен халықаралық өнім командаларындағы senior жауапкершілікке дейін.","signals.1.label":"пайдаланушыға қызмет көрсетілді","signals.1.note":"Маңызды бизнес ауқымында жұмыс істейтін production интерфейстер.","signals.2.label":"жоба тапсырылды","signals.2.note":"Веб, мобильді және деректерге бай платформалар бойынша.","signals.3.label":"жоба оңтайландырылды","signals.3.note":"Өнімділік, архитектура және қолдауға жарамдылықты жақсарту.","case_studies.01.kicker":"Өнім ауқымындағы архитектура","case_studies.01.title":"Он модульді бір жүйедей сезіндіру.","case_studies.01.problem":"Жылына миллионнан астам пайдаланушыға қызмет көрсететін платформада 10+ модуль қатар дамып жатқанда, өсіп келе жатқан Vue өнімінің беті бірізді болып қалуы керек еді.","case_studies.01.solution":"Composition, роутинг, күй және ортақ өнім сценарийлері айналасында қайта пайдалануға болатын Vue 3 / TypeScript үлгілерін анықтадым, сол арқылы жаңа функциялар жергілікті келісімдерден емес, дайын жүйеден басталатын болды.","case_studies.01.result":"Архитектура функцияны іске асыру уақытын шамамен 30%-ға қысқартты және модульаралық дамуға берік негіз қалады.","case_studies.01.metrics.0.label":"өнім модулі","case_studies.01.metrics.1.label":"функцияны тезірек жеткізу","case_studies.02.kicker":"Архитектура ретіндегі өнімділік","case_studies.02.title":"Жүктелу уақытын санмен емес, графикпен қарау.","case_studies.02.problem":"Жоғары трафикті экрандар бір анық тар жерден емес, рендеринг, деректерді алу, кэштеу және асинхронды UI ағындары арасында бөлінген жұмыстан баяулап жатты.","case_studies.02.solution":"Сұраныстан рендерге дейінгі бүкіл жолды оңтайландырдым: рендеринг тәртібін, кэштеуді, асинхронды оркестрацияны және API сұраныс үлгілерін, содан кейін бұл жұмысты Core Web Vitals, Lighthouse, тесттер және Sentry мониторингімен нығайттым.","case_studies.02.result":"Платформа дами беруіне қарамастан, беттің орташа жүктелу уақыты шамамен 3.2 секундтан 2.1 секундқа дейін қысқарды.","case_studies.02.metrics.0.label":"орташа бет жүктелуі","case_studies.02.metrics.1.label":"шамамен төмендеу","case_studies.03.kicker":"Геодеректер өнімділігі","case_studies.03.title":"Жарты миллион карта нысаны әлі де интерактивті болуы тиіс.","case_studies.03.problem":"Тығыз GIS интерфейстері бірінші өзара әрекеттесуді байқалатындай баяулатпай, шамамен 300–500 мың геокеңістіктік нысаннан тұратын деректер жиынын рендерлеп, өңдеуі керек болды.","case_studies.03.solution":"Қабаттар мен стильдерді қайта құрдым, кластерлеу мен клиент жағындағы сүзгілеуді енгіздім және Vuex–Elasticsearch деректер жолындағы қайталанатын жұмысты жойдым.","case_studies.03.result":"Mapbox GL JS бастапқы рендерингі шамамен 800 мс-тан 480 мс-қа дейін төмендеді, ал алгоритмдер бойынша бөлек жұмыс геоіздеу жылдамдығын 30%-ға жақсартты.","case_studies.03.metrics.0.label":"бастапқы карта рендері","case_studies.03.metrics.1.label":"геокеңістіктік нысан","case_studies.04.kicker":"Қайта пайдалануға болатын жеткізу жүйелері","case_studies.04.title":"Келесі аймақтық өнімді көшіру арқылы емес, баптау арқылы құру.","case_studies.04.problem":"Ондаған аймақтық GIS өнімдері бір-біріне ұқсас UI және деректер үлгілерін қайталады, бірақ қайта іске асыру жеткізуді баяулатып, бірізділікті қымбаттатты.","case_studies.04.solution":"100+ қайта пайдалануға болатын Vue компоненттері мен ортақ модульдерден тұратын орталықтандырылған архитектура жасадым, содан кейін оның айналасында BEM, теминг, рөлге негізделген үлгілер, линтинг және тестілеу тәжірибелерін стандарттадым.","case_studies.04.result":"Ұқсас іске асыру жұмысы 50%-ға дейін азайды; бұрын шамамен бір ай алатын кейбір іске қосулар енді шамамен бір аптаға сыятын болды.","case_studies.04.metrics.0.label":"қайта пайдаланылатын компонент","case_studies.04.metrics.1.label":"ұқсас іске асыру","surfaces.A.title":"Жоғары трафикті өнім модульдері","surfaces.A.text":"Архитектура, кэштеу, күй және API тәртібі бір өнім жүйесі ретінде жұмыс істеуі тиіс интерфейстер.","surfaces.B.title":"Геокеңістіктік жүйелер","surfaces.B.text":"Деректер көлемі тек рендеринг қабатын емес, фронтенд архитектурасының өзін өзгертетін карта негізіндегі өнімдер.","surfaces.C.title":"Модернизация бағдарламалары","surfaces.C.text":"Техникалық негіз өзгеріп жатқанда өнімді жеткізуді тоқтатпайтын legacy-ден заманауи стекке көшу.","surfaces.D.title":"End-to-end өнім жеткізу","surfaces.D.text":"API-ды, интеграция шекараларын және production тәртібін меңгеруге жеткілікті backend тереңдігі бар frontend-бағытталған инженерия.","principles.01.title":"Алдымен өлшеу, содан кейін қайта жазу.","principles.01.text":"Өнімділік өзгерісі дәлелден басталып, пайдаланушыға көрінетін нәтижемен аяқталуы керек.","principles.02.title":"Архитектура — жеткізу құралы.","principles.02.text":"Ең жақсы абстракция — келесі функцияны арзандатып, қауіпсіз әрі түсінікті ететін абстракция.","principles.03.title":"Frontend — жүйенің бір бөлігі.","principles.03.text":"Рендеринг, деректер пішіні, API, қолжетімділік, бақылаушылық және релиз конвейерлері — бір инженерлік аймақ.","principles.04.title":"Senior болу — белгісіздікті азайту деген сөз.","principles.04.text":"Техникалық көшбасшылық — командаға жасырын тәуекел жинамай тез қозғалуға мүмкіндік беру үшін ымыраларды көрінетін ету.","milestones.ciklum.role":"Senior Software Engineer","milestones.ciklum.focus":"Frontend архитектурасы · өнімді модернизациялау · өнімділік · техникалық көшбасшылық","milestones.keyhorse.role":"Middle → Senior → Team Lead Software Engineer","milestones.keyhorse.focus":"GIS · цифрлық қосарлар · инженерлік көшбасшылық · қайта пайдаланылатын жүйелер · backend API","milestones.dar.role":"Junior Software Engineer","milestones.dar.focus":"Көлемді веб-жеткізу · e-commerce · мобильді қосымшалар · өнімділік","milestones.epam.role":"Software Engineer Intern","milestones.epam.focus":"React · TypeScript · қайта пайдаланылатын UI · инженерлік негіздер","milestones.freelance.role":"Freelance Software Engineer","milestones.freelance.focus":"Vue/React бойынша фриланс әзірлеу · SaaS және e-commerce толық циклді жеткізу · клиенттермен жұмыс","milestones.ciklum.location":"Бухарест, Румыния (қашықтан)","milestones.ciklum.summary":"Халықаралық цифрлық өнімдер мен корпоративтік бағдарламалық трансформация саласындағы жаһандық көшбасшы, Ұлыбританияда орналасқан.","milestones.ciklum.highlight_0.label":"Архитектура","milestones.ciklum.highlight_0.text":"10+ модуль (1–3 млн пайдаланушы) бойынша WCAG AA стандартына сай, ортақ Vue 3/қатаң TypeScript компонент кітапханасы мен типі қауіпсіз REST/GraphQL API қабатын құрдым — бұл функцияларды іске асыру уақытын ~30%-ға қысқартты.","milestones.ciklum.highlight_1.label":"Техникалық көшбасшылық","milestones.ciklum.highlight_1.text":"6 инженерден тұратын команда үшін спринт жоспарлауы мен backlog реттеуін жүргізіп, frontend архитектуралық шешімдер қабылдадым; аптасына ~15 GitLab merge-request шолуын өткіздім, merge кейінгі ақауларды 35%-ға азайттым.","milestones.ciklum.highlight_2.label":"Өнімділік және Core Web Vitals","milestones.ciklum.highlight_2.text":"Жоғары жүктемелі модульдерде рендеринг, кэштеу және желілік сұрау үлгілерін оңтайландырып, өзара әрекеттесу кідірісін (INP) ~280 мс-тан ~150 мс-қа дейін төмендеттім және қайталанатын API шақыруларын 40%-ға азайттым.","milestones.ciklum.highlight_3.label":"Модернизация және сенімділік","milestones.ciklum.highlight_3.text":"Ескі Vue 2 кодтық базасын Vue 3, Composition API, Pinia және Vite-ке жаңарттым, бума өлшемін 20%-ға кішірейттім; Vitest/Jest тестілеуі, Sentry мониторингі және CI/CD жұмыс ағындары арқылы сенімділікті арттырдым.","milestones.ciklum.highlight_4.label":"Құралдар, мобильді және AI","milestones.ciklum.highlight_4.text":"Кодтық базаны Feature-Sliced Design және TanStack Query арқылы құрылымдадым, стандартты кодты ~25%-ға азайттым; дизайн-жүйені Ionic/Capacitor мобильді қосымшасына кеңейттім және AI көмегімен дамыту құралдарын (Cursor, Claude Code) енгіздім.","milestones.keyhorse.location":"Алматы, Қазақстан","milestones.keyhorse.summary":"Орталық Азияға қызмет көрсететін GIS және цифрлық қосар платформалары компаниясы.","milestones.keyhorse.roles.team-lead.label":"Team Lead","milestones.keyhorse.roles.team-lead.highlight_0.label":"Инженерлік көшбасшылық","milestones.keyhorse.roles.team-lead.highlight_0.text":"3 қосалқы командадан тұратын 18 әзірлеушіден тұратын инженерлік департаментті басқардым, Scrum-ға көшуге жетекшілік еттім және 4 елдегі 1,5 млн+ белсенді пайдаланушыға қызмет көрсететін 80+ ірі аймақтық және 100+ кіші цифрлық қосар жобаларын жеткізу үшін техникалық бағытты айқындадым.","milestones.keyhorse.roles.team-lead.highlight_1.label":"Дербес өнім жеткізу","milestones.keyhorse.roles.team-lead.highlight_1.text":"10 корпоративтік платформаны нөлден бастап дербес жобалап, әрқайсысын 1–1,5 айда іске қостым, бұл компанияның тарихи орташа көрсеткішімен салыстырғанда time-to-market-ті ~2 есе қысқартты.","milestones.keyhorse.roles.team-lead.highlight_2.label":"Процесс және басқару","milestones.keyhorse.roles.team-lead.highlight_2.text":"Спринт жоспарлауын, бағалауды және техникалық құжаттаманы жүргіздім, аптасына ~50 код шолуын өткіздім және жаңа қызметкерлердің бейімделу уақытын 40%-ға қысқартқан құжаттама стандарттарын енгіздім.","milestones.keyhorse.roles.mid-senior.label":"Middle → Senior","milestones.keyhorse.roles.mid-senior.highlight_0.label":"Геокеңістіктік өнімділік","milestones.keyhorse.roles.mid-senior.highlight_0.text":"Mapbox GL JS рендеринг уақытын 40%-ға (800 мс-тан 480 мс-қа дейін) қысқарттым және мемоизацияланған Vuex getter-лерімен Elasticsearch индекстеу/сұрау үлгілерін қайта құрдым, бұл 500 мың+ гео-объект бойынша іздеу кідірісін 30%-ға азайтты.","milestones.keyhorse.roles.mid-senior.highlight_1.label":"Frontend архитектурасы","milestones.keyhorse.roles.mid-senior.highlight_1.text":"Командалар арасында UI үлгілерін стандарттау үшін ортақ Storybook компонент кітапханасында құжатталған ортақ Vue архитектурасын (100+ FSD компоненті) жобаладым — бұл функцияларды дамыту циклінің уақытын 50%-ға қысқартты.","milestones.keyhorse.roles.mid-senior.highlight_2.label":"Backend және деректер дизайны","milestones.keyhorse.roles.mid-senior.highlight_2.text":"Ірі геокеңістіктік деректер жиынтықтары үшін Redis кэштеуі мен оңтайландырылған PL/pgSQL сақталған процедуралары бар 35+ Django/PostgreSQL REST endpoint-терін әзірледім, frontend интеграциясы үшін типі қауіпсіз API клиенттерін генерациялай отырып, 99,9% production жұмыс уақытын сақтадым.","milestones.keyhorse.roles.mid-senior.highlight_3.label":"DevOps және автоматтандыру","milestones.keyhorse.roles.mid-senior.highlight_3.text":"Vitest, Playwright және Cypress тестілеу стратегиясын жобаладым және 86 репозиторий бойынша біріктірілген GitLab CI/CD pipeline-дары арқылы production сапа қақпаларын енгіздім, код қамтуын 70–80%-ға көтердім және регрессиялық қателерді 30%-ға азайттым.","milestones.keyhorse.roles.mid-senior.highlight_4.label":"Дизайн жүйелері және WCAG","milestones.keyhorse.roles.mid-senior.highlight_4.text":"WCAG AA стандартына сай дизайн токендерін, SCSS және BEM әдіснамасын қолданатын CSS фреймворкін әзірледім, UI іске асыру уақытын ~3 күннен ~4 сағатқа дейін қысқарттым.","milestones.dar.summary":"Финтех, білім беру, спорт және бизнес операциялары саласында цифрлық өнімдер мен платформалар әзірлейтін технологиялық топ.","milestones.dar.highlight_0.label":"Production архитектурасы","milestones.dar.highlight_0.text":"Бір мезгілде 3–4 параллель жобаны басқара отырып, 30+ көп беттік production қосымшасын (әрқайсысы 8+ бет) жеткіздім, қайта пайдаланылатын Vue/React компонент кітапханасы (34 компонент, BEM архитектурасы) арқылы жеткізу уақытын 25%-ға (циклге 5–10 күн) қысқарттым.","milestones.dar.highlight_1.label":"Платформаны жеткізу","milestones.dar.highlight_1.text":"Тамақ жеткізу және тұрғын үй брондау платформаларын — GSAP анимациясымен қоса — әрқайсысын ~1 айда дербес жобалап іске қостым, 3 қаладағы 150–200 мейрамхана мен 100–150 жылжымайтын мүлік тізімін қолдадым.","milestones.dar.highlight_2.label":"Өнімділік және SEO","milestones.dar.highlight_2.text":"SSR, code splitting, жалқау жүктеу және буманы оңтайландыру арқылы бет жүктелу уақытын 40%-ға (1,8–2,2 с-қа дейін) қысқарттым, көптеген жобаларда Lighthouse SEO бойынша 100/100 көрсеткішіне жеттім.","milestones.dar.highlight_3.label":"Кросс-платформалық әзірлеу","milestones.dar.highlight_3.text":"Ionic, Capacitor және React Native арқылы 5–7 production мобильді қосымшасын (iOS/Android) шығардым, платформалар арасында кодтың 40–50%-ын қайта пайдаландым.","milestones.dar.highlight_4.label":"Backend және API","milestones.dar.highlight_4.text":"Осы қосымшалардың 6-уы үшін Laravel/MySQL REST backend-терін — API дизайны, дерекқор схемасы және аутентификация — әзірледім және қолдадым, күніне 15 мың+ сұранысты өңдедім.","milestones.epam.summary":"Жаһандық IT-консалтинг және цифрлық инжиниринг компаниясы.","milestones.epam.highlight_0.label":"Бәсекелі іріктеу","milestones.epam.highlight_0.text":"Бәсекелі техникалық іріктеу процесінде 40+ үміткер арасынан таңдалған 3 инженердің бірі болдым.","milestones.epam.highlight_1.label":"Frontend әзірлеу","milestones.epam.highlight_1.text":"React/TypeScript-те бейімделгіш интерфейстер мен қайта пайдаланылатын компонент кітапханаларын әзірледім, API-ларды production жұмыс үрдістеріне біріктірдім; 5+ корпоративтік ішкі құралға үлес қостым.","milestones.epam.highlight_2.label":"Кәсіби өсу","milestones.epam.highlight_2.text":"Корпоративтік деңгейдегі код шолуларына, unit-тестілеуге және жеткізу стандарттарына қатыстым — бұл кейінгі әрбір рөлге негіз болды.","milestones.freelance.location":"Қашықтан (халықаралық клиенттер)","milestones.freelance.summary":"Негізгі жұмыспен қатар жүргізілген, халықаралық клиенттер үшін дербес фриланс және келісімшарттық жұмыс.","milestones.freelance.highlight_0.label":"Клиенттерге жеткізу","milestones.freelance.highlight_0.text":"40+ халықаралық Vue/React жобасын (SaaS, e-commerce) мерзімін 100% сақтап және 5.0 рейтингпен жеткіздім, клиентпен алғашқы талқылаудан production-ға дейінгі толық SDLC-ге жауап бердім, соның ішінде күрделі үшінші тарап API интеграцияларын жүзеге асырдым.","proof_items.0.label":"Білім","proof_items.0.value":"Ақпараттық жүйелер","proof_items.0.note":"Сулейман Демирел атындағы университет · 2018–2022 · GPA 3.72 / 4.0","proof_items.1.label":"Ағылшын тілі","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"Академиялық IELTS · CEFR C1 нәтижесі","proof_items.2.label":"Марапат","proof_items.2.value":"Күміс медаль","proof_items.2.note":"Infomatrix Asia-Pacific 2018 — халықаралық компьютерлік жобалар байқауы.","proof_items.3.label":"Ұсыныс","proof_items.3.value":"KeyHorse","proof_items.3.note":"Компания басшылығының қолы қойылған ұсынысы","proof_items.4.label":"Тілдер","proof_items.4.value":"5 тіл","proof_items.4.note":"Ағылшын тілі — еркін жұмыс деңгейінде · Қазақ және орыс тілдері — ана тілі · Түрік тілі — сөйлесу деңгейінде · Қытай тілі — бастапқы деңгейде","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"Академиялық IELTS нәтижесі (CEFR C1) — халықаралық, remote-first инженерлік рөлдерге жарамды еркін кәсіби ағылшын тілінің дәлелі.","proof_documents.chinese-proficiency.title":"Қытай тілін білу деңгейі","proof_documents.chinese-proficiency.description":"Трансшекаралық өнім және бизнес командаларымен кәсіби жұмыс барысында дамыған қытай тілінің бастапқы деңгейі.","proof_documents.infomatrix.title":"Күміс медаль — Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"Алғашқы инженерлік жобаның бірі үшін халықаралық компьютерлік жобалар байқауындағы марапат.","proof_documents.keyhorse.title":"Ұсыныс хаты — KeyHorse","proof_documents.keyhorse.description":"KeyHorse бланкісінде Жасұланды senior деңгейіндегі инженерлік лауазымға ұсынатын, қолы қойылған ұсыныс хаты.","projects.geonomix.description":"Аймақтық енгізулерде интерактивті карталарды, муниципалдық деректерді, цифрлық тізілімдерді, мемлекеттік қызметтер мен мониторинг құралдарын біріктіретін ауқымды геокеңістіктік және цифрлық қосарлар платформасы.","projects.midas-event.description":"Статикалық қызметтер тізімі емес, өткен іс-шаралардың шолуға болатын портфолиосы ретінде құрылған, React негізіндегі интерактивті мазмұны бар event-агенттігінің сайты.","projects.kostyum.description":"Тауар каталогына арналған қайта пайдаланылатын UI-мен және десктоп пен мобильдегі тегіс сатып алу тәжірибесіне бағытталған ерлер сән e-commerce фронтенді.","projects.unistory.description":"Крипто-әмиян күйі мен асинхронды backend деректерін қайта пайдаланылатын React өнім компоненттеріне біріктіретін цифрлық өнім интерфейсі.","projects.kazmed.description":"Ұзақ мәтінді беттердің орнына Swiper негізіндегі каталог айналасында құрылған, авторизацияланған медициналық жабдық қызмет серіктесіне арналған корпоративтік фронтенд.","projects.dostyk-trans-terminal.description":"Достық–Алашанькоу шекара өткелінде контейнерлерді өңдеу, сақтау және тасымалдау қызметтерін көрсететін логистикалық терминалдың корпоративтік сайты.","projects.melissa.description":"13 000+ тауары бар ірі онлайн-дәріхана: каталог навигациясы, іздеу, сүзгілеу, сұрыптау, тауар беттері, себет ағыны және backend интеграциялары.","projects.abi-construction.description":"WordPress контент-бэкендін Vue негізіндегі интерактивті жоба галереяларымен біріктірген құрылыс компаниясының сайты.","projects.tahit.description":"Тоқыма өндірісінің мүмкіндіктерін, технологияларын, өнімдері мен қызметтерін десктоп пен мобильде көрсететін өндірістік компанияның фронтенді.","projects.dobraya.description":"Бейімделгіш каталогтары, санат навигациясы, іздеу, сүзгілеу және тапсырыс ағындары бар онлайн-дәріхана витринасы.","projects.asia-mebel.description":"Құрылымдалған навигациясы, сүзгілеуі, іздеуі және тауар беттері бар жиһаз материалдары, фурнитура, құралдар мен қызметтердің коммерциялық каталогы.","projects.pharmacom.description":"Бір статикалық басты бет емес, орналасу, қызметтер және пациент ақпараты айналасында құрылған вакцинация клиникасы мен дәріхана желісіне арналған сайт.","projects.navat.description":"Мәзір, атмосфера және бренд бірегейлігі айналасында құрылған, бейімделгіш көрнекі тәжірибесі бар мейрамхананың жарнамалық лендингі.","projects.asia-credit-bank.description":"Тауар мен қолдау беттерінің үлкен жиынын клиенттерге арналған жылдам, ыңғайлы навигациялы құрылымға айналдыратын банктің байланыс орталығы сайты.","projects.geonomix.note":"Карта басты орында тұрған өнім, мұнда деректер көлемі мен қайта пайдаланылатын аймақтық жеткізу фронтенд архитектурасын қалыптастырды.","projects.melissa.note":"Ақпараттық архитектура UI жылтырлығы сияқты маңызды болатын үлкен каталог тәжірибесі."},l={"signals.0.label":"yıl production deneyimi","signals.0.note":"React stajyerliğinden uluslararası ürün ekiplerinde senior sorumluluğa.","signals.1.label":"kullanıcıya ulaşıldı","signals.1.note":"Anlamlı bir ürün ölçeğinde çalışan production arayüzleri.","signals.2.label":"proje teslim edildi","signals.2.note":"Web, mobil ve veri yoğun platformlar genelinde.","signals.3.label":"proje optimize edildi","signals.3.note":"Performans, mimari ve sürdürülebilirlik iyileştirmeleri.","case_studies.01.kicker":"Ürün ölçeğinde mimari","case_studies.01.title":"On modülü tek bir sistem gibi hissettirmek.","case_studies.01.problem":"Büyüyen bir Vue ürün yüzeyinin, yılda bir milyondan fazla kullanıcıya hizmet veren bir platformda 10+ modül paralel geliştirilirken tutarlı kalması gerekiyordu.","case_studies.01.solution":"Composition, routing, state ve ortak ürün akışları etrafında yeniden kullanılabilir Vue 3 / TypeScript kalıpları tanımladım; böylece yeni özellikler yerel kurallardan değil, kurulu bir sistemden başlayabildi.","case_studies.01.result":"Bu mimari, özellik geliştirme süresini yaklaşık %30 azalttı ve modüller arası geliştirme için daha güçlü bir temel oluşturdu.","case_studies.01.metrics.0.label":"ürün modülü","case_studies.01.metrics.1.label":"daha hızlı özellik teslimi","case_studies.02.kicker":"Mimari olarak performans","case_studies.02.title":"Yüklenme süresini bir sayı değil, bir grafik olarak ele almak.","case_studies.02.problem":"Yoğun trafikli ekranlar, tek bir belirgin darboğazdan değil; render, veri çekme, önbellekleme ve asenkron UI akışları arasında dağılmış işlerden yavaşlıyordu.","case_studies.02.solution":"İstekten render'a kadar tüm yolu optimize ettim: render davranışı, önbellekleme, asenkron orkestrasyon ve API istek kalıpları; bu çalışmayı Core Web Vitals, Lighthouse, testler ve Sentry izlemesiyle destekledim.","case_studies.02.result":"Platform gelişmeye devam ederken ortalama sayfa yüklenme süresi yaklaşık 3.2 saniyeden 2.1 saniyeye düştü.","case_studies.02.metrics.0.label":"ortalama sayfa yüklenmesi","case_studies.02.metrics.1.label":"yaklaşık azalma","case_studies.03.kicker":"Coğrafi veri performansı","case_studies.03.title":"Yarım milyon harita nesnesi hâlâ etkileşimli hissettirmeli.","case_studies.03.problem":"Yoğun GIS arayüzlerinin, ilk etkileşimi belirgin şekilde geciktirmeden yaklaşık 300-500 bin coğrafi nesne içeren veri kümelerini render edip işlemesi gerekiyordu.","case_studies.03.solution":"Katmanları ve stilleri yeniden yapılandırdım, kümeleme ve istemci tarafı filtreleme ekledim; Vuex-Elasticsearch veri yolundaki tekrar eden işleri ortadan kaldırdım.","case_studies.03.result":"İlk Mapbox GL JS render süresi yaklaşık 800 ms'den 480 ms'ye düştü; ayrı bir algoritma çalışmasıyla coğrafi arama yanıt süresinde %30 iyileşme sağlandı.","case_studies.03.metrics.0.label":"ilk harita render'ı","case_studies.03.metrics.1.label":"coğrafi nesne","case_studies.04.kicker":"Yeniden kullanılabilir teslimat sistemleri","case_studies.04.title":"Bir sonraki bölgesel ürünü kopyalayarak değil, yapılandırarak inşa etmek.","case_studies.04.problem":"Onlarca bölgesel GIS ürünü aynı UI ve veri kalıplarını tekrarlıyordu; ancak tekrar eden uygulamalar teslimatı yavaşlatıp tutarlılığı pahalı hale getiriyordu.","case_studies.04.solution":"100+ yeniden kullanılabilir Vue bileşeni ve ortak modülden oluşan merkezi bir mimari kurdum, ardından bunun etrafında BEM, temalandırma, role dayalı kalıplar, lint ve test pratiklerini standartlaştırdım.","case_studies.04.result":"Benzer uygulama işleri %50'ye kadar azaldı; önceden yaklaşık bir ay süren bazı lansmanlar artık yaklaşık bir haftaya sığabiliyor.","case_studies.04.metrics.0.label":"yeniden kullanılabilir bileşen","case_studies.04.metrics.1.label":"benzer uygulama","surfaces.A.title":"Yoğun trafikli ürün modülleri","surfaces.A.text":"Mimarinin, önbelleklemenin, state'in ve API davranışının tek bir ürün sistemi gibi çalışması gereken arayüzler.","surfaces.B.title":"Coğrafi bilgi sistemleri","surfaces.B.text":"Veri hacminin sadece render katmanını değil, frontend mimarisinin kendisini değiştirdiği harita ağırlıklı ürünler.","surfaces.C.title":"Modernizasyon programları","surfaces.C.text":"Teknik temel değişirken ürün teslimatını durdurmayan legacy-den moderne geçiş süreçleri.","surfaces.D.title":"Uçtan uca ürün teslimatı","surfaces.D.text":"API'lere, entegrasyon sınırlarına ve production davranışına sahip çıkacak kadar derin backend bilgisiyle desteklenen frontend odaklı mühendislik.","principles.01.title":"Yeniden yazmadan önce ölç.","principles.01.text":"Bir performans değişikliği kanıtla başlamalı ve kullanıcının görebileceği bir sonuçla bitmeli.","principles.02.title":"Mimari bir teslimat aracıdır.","principles.02.text":"En iyi soyutlama, bir sonraki özelliği daha ucuz, daha güvenli ve daha anlaşılır hale getirendir.","principles.03.title":"Frontend, sistemin bir parçasıdır.","principles.03.text":"Render, veri şekli, API'ler, erişilebilirlik, gözlemlenebilirlik ve dağıtım süreçleri tek bir mühendislik alanıdır.","principles.04.title":"Senior olmak, belirsizliği azaltmak demektir.","principles.04.text":"Teknik liderlik, ekibin gizli risk biriktirmeden hızlı ilerleyebilmesi için ödünleşimleri görünür kılmaktır.","milestones.ciklum.role":"Senior Software Engineer","milestones.ciklum.focus":"Frontend mimarisi · ürün modernizasyonu · performans · teknik liderlik","milestones.keyhorse.role":"Middle → Senior → Team Lead Software Engineer","milestones.keyhorse.focus":"GIS · dijital ikizler · mühendislik liderliği · yeniden kullanılabilir sistemler · backend API’ler","milestones.dar.role":"Junior Software Engineer","milestones.dar.focus":"Yüksek hacimli web teslimatı · e-ticaret · mobil · performans","milestones.epam.role":"Software Engineer Intern","milestones.epam.focus":"React · TypeScript · yeniden kullanılabilir UI · mühendislik temelleri","milestones.freelance.role":"Freelance Software Engineer","milestones.freelance.focus":"Freelance Vue/React geliştirme · uçtan uca SaaS ve e-ticaret teslimatı · müşteri yönetimi","milestones.ciklum.location":"Bükreş, Romanya (Uzaktan)","milestones.ciklum.summary":"Birleşik Krallık merkezli, küresel dijital ürün ve kurumsal yazılım dönüşümü lideri.","milestones.ciklum.highlight_0.label":"Mimari","milestones.ciklum.highlight_0.text":"10+ modül (1–3M kullanıcı) genelinde WCAG AA standardına uygun, paylaşılan bir Vue 3/strict TypeScript bileşen kütüphanesi ve tip güvenli REST/GraphQL API katmanı kurdum; bu, özellik geliştirme süresini ~%30 azalttı.","milestones.ciklum.highlight_1.label":"Teknik Liderlik","milestones.ciklum.highlight_1.text":"6 kişilik bir mühendislik ekibi için sprint planlamasını ve backlog düzenlemesini yöneterek frontend mimari kararları aldım; haftada ~15 GitLab merge-request incelemesi yaparak merge-sonrası hataları %35 azalttım.","milestones.ciklum.highlight_2.label":"Performans ve Core Web Vitals","milestones.ciklum.highlight_2.text":"Yoğun trafikli modüllerde render, önbellekleme ve ağ isteği desenlerini optimize ederek etkileşim gecikmesini (INP) ~280ms’den ~150ms’ye düşürdüm ve yinelenen API çağrılarını %40 azalttım.","milestones.ciklum.highlight_3.label":"Modernizasyon ve Güvenilirlik","milestones.ciklum.highlight_3.text":"Eski Vue 2 kod tabanlarını Vue 3, Composition API, Pinia ve Vite’a modernize ederek bundle boyutunu %20 küçülttüm; Vitest/Jest testleri, Sentry izleme ve CI/CD iş akışlarıyla güvenilirliği artırdım.","milestones.ciklum.highlight_4.label":"Araçlar, Mobil ve AI","milestones.ciklum.highlight_4.text":"Kod tabanlarını Feature-Sliced Design ve TanStack Query ile yapılandırarak şablon kodu ~%25 azalttım; tasarım sistemini Ionic/Capacitor tabanlı bir mobil uygulamaya genişlettim ve AI destekli geliştirme araçlarını (Cursor, Claude Code) devreye aldım.","milestones.keyhorse.location":"Almatı, Kazakistan","milestones.keyhorse.summary":"Orta Asya’ya hizmet veren bir GIS ve dijital ikiz platformu şirketi.","milestones.keyhorse.roles.team-lead.label":"Team Lead","milestones.keyhorse.roles.team-lead.highlight_0.label":"Mühendislik Liderliği","milestones.keyhorse.roles.team-lead.highlight_0.text":"3 alt ekipte 18 geliştiriciden oluşan bir mühendislik departmanını yönettim, Scrum’a geçişe öncülük ettim ve 4 ülkede 1,5M+ aktif kullanıcıya hizmet veren 80+ büyük ölçekli bölgesel ve 100+ daha küçük dijital ikiz projesinin teknik yönünü belirledim.","milestones.keyhorse.roles.team-lead.highlight_1.label":"Bağımsız Ürün Teslimatı","milestones.keyhorse.roles.team-lead.highlight_1.text":"10 kurumsal platformu sıfırdan bağımsız olarak tasarlayıp her birini 1–1,5 ayda başlattım; bu, şirketin tarihsel ortalamasına göre time-to-market’i ~2 kat hızlandırdı.","milestones.keyhorse.roles.team-lead.highlight_2.label":"Süreç ve Yönetişim","milestones.keyhorse.roles.team-lead.highlight_2.text":"Sprint planlamasını, tahminlemeyi ve teknik dokümantasyonu yönettim, haftada ~50 kod incelemesi yaptım ve yeni işe alım oryantasyon süresini %40 azaltan dokümantasyon standartları oluşturdum.","milestones.keyhorse.roles.mid-senior.label":"Middle → Senior","milestones.keyhorse.roles.mid-senior.highlight_0.label":"Coğrafi Performans","milestones.keyhorse.roles.mid-senior.highlight_0.text":"Mapbox GL JS render süresini %40 (800ms → 480ms) azalttım ve önbelleğe alınmış Vuex getter’larla Elasticsearch indeksleme/sorgu desenlerini yeniden yapılandırarak 500K+ coğrafi nesne genelinde arama gecikmesini %30 azalttım.","milestones.keyhorse.roles.mid-senior.highlight_1.label":"Frontend Mimarisi","milestones.keyhorse.roles.mid-senior.highlight_1.text":"Ekipler arasında UI desenlerini standartlaştırmak için bir Storybook bileşen kütüphanesinde belgelenen, paylaşılan bir Vue mimarisi (100+ FSD bileşeni) tasarladım; bu, özellik geliştirme döngü süresini %50 azalttı.","milestones.keyhorse.roles.mid-senior.highlight_2.label":"Backend ve Veri Tasarımı","milestones.keyhorse.roles.mid-senior.highlight_2.text":"Büyük ölçekli coğrafi veri kümeleri için Redis önbellekleme ve optimize edilmiş PL/pgSQL saklı yordamlarıyla 35+ Django/PostgreSQL REST endpoint’i geliştirdim; frontend entegrasyonu için tip güvenli API istemcileri üretirken %99,9 production çalışma süresini korudum.","milestones.keyhorse.roles.mid-senior.highlight_3.label":"DevOps ve Otomasyon","milestones.keyhorse.roles.mid-senior.highlight_3.text":"Bir Vitest, Playwright ve Cypress test stratejisi tasarladım ve 86 repository genelinde birleşik GitLab CI/CD pipeline’ları aracılığıyla production kalite kapıları uyguladım; kod kapsamını %70–80’e çıkardım ve regresyon hatalarını %30 azalttım.","milestones.keyhorse.roles.mid-senior.highlight_4.label":"Tasarım Sistemleri ve WCAG","milestones.keyhorse.roles.mid-senior.highlight_4.text":"WCAG AA standardına uygun, tasarım token’ları, SCSS ve BEM metodolojisini kullanan bir CSS framework’ü geliştirdim; UI uygulama süresini ~3 günden ~4 saate indirdim.","milestones.dar.summary":"Fintech, eğitim, spor ve iş operasyonları alanlarında dijital ürünler ve platformlar geliştiren bir teknoloji grubu.","milestones.dar.highlight_0.label":"Production Mimarisi","milestones.dar.highlight_0.text":"Aynı anda 3–4 projeyi yönetirken 30+ çok sayfalı production uygulaması (her biri 8+ sayfa) teslim ettim; yeniden kullanılabilir bir Vue/React bileşen kütüphanesi (34 bileşen, BEM mimarisi) sayesinde teslimat süresini %25 (döngü başına 5–10 gün) azalttım.","milestones.dar.highlight_1.label":"Platform Teslimatı","milestones.dar.highlight_1.text":"Yemek teslimatı ve konaklama rezervasyonu olmak üzere iki tam kapsamlı platformu, GSAP destekli animasyonlar dahil, her birini ~1 ayda bağımsız olarak tasarlayıp yayına aldım; 3 şehirde 150–200 restoran ve 100–150 mülk ilanını destekledim.","milestones.dar.highlight_2.label":"Performans ve SEO","milestones.dar.highlight_2.text":"SSR, code splitting, lazy loading ve bundle optimizasyonu ile sayfa yüklenme sürelerini %40 (1,8–2,2s’ye) kısalttım ve çoğu projede Lighthouse SEO puanında 100/100’e ulaştım.","milestones.dar.highlight_3.label":"Çapraz Platform Geliştirme","milestones.dar.highlight_3.text":"Ionic, Capacitor ve React Native kullanarak 5–7 production mobil uygulaması (iOS/Android) yayınladım; platformlar arasında %40–50 kod paylaşımı sağladım.","milestones.dar.highlight_4.label":"Backend ve API’ler","milestones.dar.highlight_4.text":"Bu uygulamaların 6’sı için Laravel/MySQL REST backend’lerini — API tasarımı, veritabanı şeması ve kimlik doğrulama dahil — geliştirdim ve sürdürdüm; günde 15K+ isteği karşıladım.","milestones.epam.summary":"Küresel BT danışmanlığı ve dijital mühendislik şirketi.","milestones.epam.highlight_0.label":"Rekabetçi Seçim","milestones.epam.highlight_0.text":"Rekabetçi bir teknik işe alım sürecinde 40+ başvuru sahibi arasından işe alınan 3 mühendisten biri olarak seçildim.","milestones.epam.highlight_1.label":"Frontend Geliştirme","milestones.epam.highlight_1.text":"Duyarlı React/TypeScript arayüzleri ve yeniden kullanılabilir bileşen kütüphaneleri geliştirdim, API’leri production iş akışlarına entegre ettim; 5+ kurumsal iç araca katkıda bulundum.","milestones.epam.highlight_2.label":"Mühendislik Gelişimi","milestones.epam.highlight_2.text":"Kurumsal düzeyde kod incelemelerine, birim testlerine ve teslimat standartlarına katıldım — bu, sonraki her rolde taşıdığım bir temel oldu.","milestones.freelance.location":"Uzaktan (uluslararası müşteriler)","milestones.freelance.summary":"Tam zamanlı rollerin yanı sıra yürütülen, uluslararası müşteriler için bağımsız freelance ve sözleşmeli çalışma.","milestones.freelance.highlight_0.label":"Müşteri Teslimatı","milestones.freelance.highlight_0.text":"40'tan fazla uluslararası Vue/React projesini (SaaS, e-ticaret) %100 zamanında teslim oranı ve 5.0 puanla tamamladım; müşteri keşfinden production'a kadar tüm SDLC'yi yönettim ve karmaşık üçüncü taraf API entegrasyonlarını gerçekleştirdim.","proof_items.0.label":"Eğitim","proof_items.0.value":"Bilişim Sistemleri","proof_items.0.note":"Suleyman Demirel Üniversitesi · 2018–2022 · Not Ortalaması 3.72 / 4.0","proof_items.1.label":"İngilizce","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"Akademik IELTS · CEFR C1 sonucu","proof_items.2.label":"Tanınırlık","proof_items.2.value":"Gümüş Madalya","proof_items.2.note":"Infomatrix Asia-Pacific 2018 — Uluslararası Bilgisayar Projesi Yarışması.","proof_items.3.label":"Referans","proof_items.3.value":"KeyHorse","proof_items.3.note":"Şirket yönetiminden imzalı referans","proof_items.4.label":"Diller","proof_items.4.value":"5 dil","proof_items.4.note":"İngilizce — tam profesyonel yeterlilik · Kazakça ve Rusça — anadil · Türkçe — konuşma düzeyi · Çince — temel düzey","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"Akademik IELTS sonucu (CEFR C1) — uluslararası, uzaktan çalışmaya uygun mühendislik rolleri için tam profesyonel İngilizce yeterliliğinin kanıtı.","proof_documents.chinese-proficiency.title":"Çince Dil Yeterliliği","proof_documents.chinese-proficiency.description":"Sınır ötesi ürün ve iş ekipleriyle yürütülen profesyonel çalışmayla birlikte geliştirilen temel düzey Çince yeterliliği.","proof_documents.infomatrix.title":"Gümüş Madalya — Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"Erken bir mühendislik projesi için Uluslararası Bilgisayar Projesi Yarışması'nda kazanılan tanınırlık.","proof_documents.keyhorse.title":"Referans Mektubu — KeyHorse","proof_documents.keyhorse.description":"Zhassulan'ı senior seviyede bir mühendislik rolü için öneren, KeyHorse antetli kağıdında imzalı bir referans mektubu.","projects.geonomix.description":"Bölgesel uygulamalarda interaktif haritaları, belediye verilerini, dijital sicilleri, kamu hizmetlerini ve izleme araçlarını bir araya getiren büyük ölçekli coğrafi bilgi ve dijital ikiz platformu.","projects.midas-event.description":"Statik bir hizmet listesi yerine geçmiş etkinliklerin gezilebilir bir portföyü olarak kurgulanmış, React tabanlı interaktif detaylara sahip bir etkinlik ajansı sitesi.","projects.kostyum.description":"Yeniden kullanılabilir ürün katalog arayüzüne sahip, masaüstü ve mobilde akıcı bir alışveriş deneyimine odaklanan responsive erkek modası e-ticaret frontend'i.","projects.unistory.description":"Kripto cüzdan durumunu ve asenkron backend verisini yeniden kullanılabilir React ürün bileşenlerine entegre eden dijital ürün arayüzü.","projects.kazmed.description":"Uzun metin sayfaları yerine Swiper tabanlı bir ekipman ve hizmet kataloğu etrafında kurulmuş, yetkili bir medikal ekipman servis ortağı için kurumsal frontend.","projects.dostyk-trans-terminal.description":"Dostyk–Alashankou sınır kapısındaki bir lojistik terminali için konteyner elleçleme, depolama ve aktarma hizmetlerini tanıtan kurumsal web sitesi.","projects.melissa.description":"13.000+ ürünlü büyük bir online eczane; katalog gezinme, arama, filtreleme, sıralama, ürün sayfaları, sepet akışları ve backend entegrasyonları içeriyor.","projects.abi-construction.description":"WordPress içerik altyapısını Vue tabanlı interaktif proje galerileriyle birleştiren bir inşaat şirketi web sitesi.","projects.tahit.description":"Tekstil üretim kapasitelerini, teknolojilerini, ürünlerini ve hizmetlerini masaüstü ve mobilde sergileyen bir üretim şirketi frontend'i.","projects.dobraya.description":"Responsive kataloglara, kategori gezinmeye, arama, filtreleme ve sipariş akışlarına sahip bir online eczane vitrini.","projects.asia-mebel.description":"Yapılandırılmış gezinme, filtreleme, arama ve ürün sayfalarına sahip mobilya malzemeleri, aksesuarlar, araçlar ve hizmetler için ticari bir katalog.","projects.pharmacom.description":"Tek bir statik ana sayfa yerine lokasyonlar, hizmetler ve hasta bilgileri etrafında organize edilmiş, bir aşı kliniği ve eczane ağı için sağlık web sitesi.","projects.navat.description":"Menü, atmosfer ve marka kimliği etrafında kurgulanmış, responsive görsel deneyime sahip tanıtım amaçlı bir restoran landing sayfası.","projects.asia-credit-bank.description":"Çok sayıda ürün ve destek sayfasını müşteriler için hızlı, kolay gezinilebilir bir yapıya dönüştüren bir banka çağrı merkezi web sitesi.","projects.geonomix.note":"Haritanın öncelikli olduğu, veri hacminin ve yeniden kullanılabilir bölgesel teslimatın frontend mimarisini şekillendirdiği bir ürün.","projects.melissa.note":"Bilgi mimarisinin UI cilası kadar önemli olduğu büyük bir katalog deneyimi."},o={"signals.0.label":"年生产环境经验","signals.0.note":"从 React 实习工作到在跨国产品团队中承担高级职责。","signals.1.label":"服务用户数","signals.1.note":"在具有实际业务规模的场景下稳定运行的生产环境界面。","signals.2.label":"个项目交付","signals.2.note":"涵盖 Web、移动端与数据密集型平台。","signals.3.label":"个项目优化","signals.3.note":"在性能、架构与可维护性方面的改进。","case_studies.01.kicker":"产品规模下的架构","case_studies.01.title":"让十个模块像一个系统一样运转。","case_studies.01.problem":"在一个年服务用户超百万的平台上，10 多个模块并行演进，日益扩张的 Vue 产品体系必须保持一致性。","case_studies.01.solution":"围绕组合式函数、路由、状态管理和通用产品流程，定义了一套可复用的 Vue 3 / TypeScript 模式，让新功能从既有体系出发，而不是各自为政。","case_studies.01.result":"该架构将功能实现时间缩短了约 30%，同时为跨模块开发打下更坚实的基础。","case_studies.01.metrics.0.label":"个产品模块","case_studies.01.metrics.1.label":"功能交付提速","case_studies.02.kicker":"性能即架构","case_studies.02.title":"把加载时间当作一张图，而不是一个数字。","case_studies.02.problem":"高流量页面变慢的原因分散在渲染、数据获取、缓存和异步 UI 流程之中，而不是某一个明显的瓶颈。","case_studies.02.solution":"优化了从请求到渲染的整条链路：渲染行为、缓存、异步编排和 API 请求模式，并借助 Core Web Vitals、Lighthouse、测试和 Sentry 监控支撑这项工作。","case_studies.02.result":"在平台持续演进的同时，平均页面加载时间从约 3.2 秒降到 2.1 秒。","case_studies.02.metrics.0.label":"平均页面加载","case_studies.02.metrics.1.label":"约降低","case_studies.03.kicker":"地理空间性能","case_studies.03.title":"五十万个地图对象依然要保持流畅交互。","case_studies.03.problem":"密集的 GIS 界面需要渲染并处理约 30 万至 50 万个地理空间对象的数据集，同时不能让首次交互变得明显迟滞。","case_studies.03.solution":"重构了图层与样式，引入聚合与客户端过滤，并精简了 Vuex 与 Elasticsearch 之间的数据链路，消除了重复计算。","case_studies.03.result":"Mapbox GL JS 的初始渲染时间从约 800 毫秒降到 480 毫秒，另外的算法优化工作又将地理搜索响应速度提升了 30%。","case_studies.03.metrics.0.label":"初始地图渲染","case_studies.03.metrics.1.label":"个地理空间对象","case_studies.04.kicker":"可复用的交付体系","case_studies.04.title":"用配置而非复制来搭建下一个区域产品。","case_studies.04.problem":"数十个区域性 GIS 产品重复着相似的 UI 与数据模式，反复实现拖慢了交付速度，也让一致性变得昂贵。","case_studies.04.solution":"构建了一套包含 100 多个可复用 Vue 组件和共享模块的集中式架构，并围绕它统一了 BEM 规范、主题、基于角色的模式、代码检查与测试实践。","case_studies.04.result":"类似功能的实现工作量最多减少 50%；一些以前需要约一个月的上线周期，现在缩短到大约一周。","case_studies.04.metrics.0.label":"个可复用组件","case_studies.04.metrics.1.label":"次类似实现","surfaces.A.title":"高流量产品模块","surfaces.A.text":"架构、缓存、状态与 API 行为必须作为同一套产品系统协同运作的界面。","surfaces.B.title":"地理空间系统","surfaces.B.text":"数据量会改变前端架构本身、而不只是渲染层的地图密集型产品。","surfaces.C.title":"现代化改造项目","surfaces.C.text":"在底层技术不断演进的同时，仍能保持产品持续交付的旧系统向现代技术栈迁移。","surfaces.D.title":"端到端的产品交付","surfaces.D.text":"以前端为主导、同时具备足够后端深度，可以掌控 API、集成边界与生产环境行为的工程实践。","principles.01.title":"先度量，再重写。","principles.01.text":"一次性能优化应当从数据出发，并以用户可感知的结果收尾。","principles.02.title":"架构是一种交付工具。","principles.02.text":"最好的抽象，是能让下一个功能开发得更便宜、更安全、更容易理解的那一种。","principles.03.title":"前端是系统的一部分。","principles.03.text":"渲染、数据结构、API、无障碍、可观测性与发布流水线，本质上是同一片工程领域。","principles.04.title":"所谓 Senior，就是降低不确定性。","principles.04.text":"技术领导力，就是把权衡取舍讲清楚，让团队能快速前进，而不是悄悄积累风险。","milestones.ciklum.role":"高级软件工程师","milestones.ciklum.focus":"前端架构 · 产品现代化改造 · 性能优化 · 技术领导力","milestones.keyhorse.role":"中级 → 高级 → 技术组长软件工程师","milestones.keyhorse.focus":"GIS · 数字孪生 · 工程领导力 · 可复用系统 · 后端 API","milestones.dar.role":"初级软件工程师","milestones.dar.focus":"高产出网页交付 · 电商 · 移动端 · 性能优化","milestones.epam.role":"软件工程实习生","milestones.epam.focus":"React · TypeScript · 可复用 UI · 工程基础","milestones.freelance.role":"Freelance Software Engineer","milestones.freelance.focus":"自由职业 Vue/React 开发 · SaaS 与电商全周期交付 · 客户管理","milestones.ciklum.location":"布加勒斯特，罗马尼亚（远程）","milestones.ciklum.summary":"总部位于英国的全球数字产品与企业软件转型领导者。","milestones.ciklum.highlight_0.label":"架构","milestones.ciklum.highlight_0.text":"在10多个模块（服务1–300万用户）中建立了统一的 Vue 3/严格模式 TypeScript 组件库和类型安全的 REST/GraphQL API 层，并达到 WCAG AA 标准，将功能实现时间缩短约30%。","milestones.ciklum.highlight_1.label":"技术领导力","milestones.ciklum.highlight_1.text":"主导前端架构决策，为6人工程团队负责冲刺计划与需求梳理；每周进行约15次 GitLab 合并请求评审，将合并后缺陷率降低35%。","milestones.ciklum.highlight_2.label":"性能与核心网页指标","milestones.ciklum.highlight_2.text":"针对高流量模块优化渲染、缓存与 API 请求模式，将交互延迟（INP）从约280毫秒降至约150毫秒，并将重复 API 调用减少40%。","milestones.ciklum.highlight_3.label":"现代化改造与可靠性","milestones.ciklum.highlight_3.text":"将遗留的 Vue 2 代码库现代化升级为 Vue 3、Composition API、Pinia 和 Vite，将打包体积缩小20%；通过 Vitest/Jest 测试、Sentry 监控与 CI/CD 工作流增强了可靠性。","milestones.ciklum.highlight_4.label":"工具链、移动端与 AI","milestones.ciklum.highlight_4.text":"使用 Feature-Sliced Design 和 TanStack Query 重构代码结构，将样板代码减少约25%；将设计系统扩展到基于 Ionic/Capacitor 的移动应用，并引入 AI 辅助开发工具（Cursor、Claude Code）。","milestones.keyhorse.location":"阿拉木图，哈萨克斯坦","milestones.keyhorse.summary":"一家服务中亚地区的 GIS 与数字孪生平台公司。","milestones.keyhorse.roles.team-lead.label":"技术组长","milestones.keyhorse.roles.team-lead.highlight_0.label":"工程领导力","milestones.keyhorse.roles.team-lead.highlight_0.text":"领导由18名开发人员组成、分为3个子团队的工程部门，主导向 Scrum 的转型，并为服务于4个国家1.5百万以上活跃用户的80多个大型区域项目和100多个较小型数字孪生项目确定技术方向。","milestones.keyhorse.roles.team-lead.highlight_1.label":"独立产品交付","milestones.keyhorse.roles.team-lead.highlight_1.text":"独立架构并从零开始上线10个企业级平台，每个耗时1–1.5个月，相较公司历史平均水平将上市时间缩短约2倍。","milestones.keyhorse.roles.team-lead.highlight_2.label":"流程与治理","milestones.keyhorse.roles.team-lead.highlight_2.text":"负责冲刺计划、工作量估算与技术文档编写，每周进行约50次代码评审，并建立文档标准，将新员工上手时间缩短40%。","milestones.keyhorse.roles.mid-senior.label":"中级 → 高级","milestones.keyhorse.roles.mid-senior.highlight_0.label":"地理空间性能优化","milestones.keyhorse.roles.mid-senior.highlight_0.text":"将 Mapbox GL JS 渲染时间降低40%（从800毫秒降至480毫秒），并通过带记忆化的 Vuex getter 重构 Elasticsearch 索引/查询模式，在50万多个地理对象范围内将搜索延迟降低30%。","milestones.keyhorse.roles.mid-senior.highlight_1.label":"前端架构","milestones.keyhorse.roles.mid-senior.highlight_1.text":"设计了统一的 Vue 架构（100多个 FSD 组件），并记录在共享的 Storybook 组件库中以统一各团队的 UI 模式，将功能开发周期缩短50%。","milestones.keyhorse.roles.mid-senior.highlight_2.label":"后端与数据设计","milestones.keyhorse.roles.mid-senior.highlight_2.text":"为大规模地理空间数据集开发了35多个 Django/PostgreSQL REST 接口，采用 Redis 缓存和优化的 PL/pgSQL 存储过程，在为前端集成生成类型安全 API 客户端的同时保持99.9%的生产环境正常运行时间。","milestones.keyhorse.roles.mid-senior.highlight_3.label":"DevOps 与自动化","milestones.keyhorse.roles.mid-senior.highlight_3.text":"设计了 Vitest、Playwright 和 Cypress 测试策略，并通过统一的 GitLab CI/CD 流水线在86个代码仓库中实施生产质量门禁，将代码覆盖率提升至70–80%，并将回归缺陷减少30%。","milestones.keyhorse.roles.mid-senior.highlight_4.label":"设计系统与 WCAG","milestones.keyhorse.roles.mid-senior.highlight_4.text":"基于设计令牌、SCSS 和 BEM 方法论开发了符合 WCAG AA 标准的 CSS 框架，将 UI 实现时间从约3天缩短至约4小时。","milestones.dar.summary":"一家在金融科技、教育、体育和商业运营领域开发数字产品与平台的技术集团。","milestones.dar.highlight_0.label":"生产架构","milestones.dar.highlight_0.text":"在同时管理3–4个并行项目的情况下交付了30多个多页面生产应用（每个8页以上），通过可复用的 Vue/React 组件库（34个组件，BEM 架构）将交付时间缩短25%（每个周期5–10天）。","milestones.dar.highlight_1.label":"平台交付","milestones.dar.highlight_1.text":"独立架构并上线了两个全功能平台——外卖配送和住宿预订——每个耗时约1个月，包含 GSAP 驱动的动画，支持3个城市150–200家餐厅和100–150个房源。","milestones.dar.highlight_2.label":"性能与 SEO","milestones.dar.highlight_2.text":"通过 SSR、代码分割、懒加载和打包优化，将页面加载时间缩短40%（降至1.8–2.2秒），大多数项目的 Lighthouse SEO 得分达到100/100。","milestones.dar.highlight_3.label":"跨平台开发","milestones.dar.highlight_3.text":"使用 Ionic、Capacitor 和 React Native 发布了5–7款生产环境移动应用（iOS/Android），跨平台共享40–50%的代码。","milestones.dar.highlight_4.label":"后端与 API","milestones.dar.highlight_4.text":"为其中6个应用开发并维护了 Laravel/MySQL REST 后端——包括 API 设计、数据库架构与身份验证——每日处理超过1.5万次请求。","milestones.epam.summary":"一家全球性的 IT 咨询与数字工程公司。","milestones.epam.highlight_0.label":"竞争性选拔","milestones.epam.highlight_0.text":"在竞争激烈的技术招聘流程中，从40多名申请者中脱颖而出，成为被录用的3名工程师之一。","milestones.epam.highlight_1.label":"前端开发","milestones.epam.highlight_1.text":"构建了响应式 React/TypeScript 界面和可复用组件库，将 API 集成到生产工作流中；为5个以上企业内部工具做出贡献。","milestones.epam.highlight_2.label":"工程能力成长","milestones.epam.highlight_2.text":"参与了企业级代码评审、单元测试和交付标准的实践——这一基础延续到了之后的每一个职位中。","milestones.freelance.location":"远程（国际客户）","milestones.freelance.summary":"在全职工作之余为国际客户提供独立自由职业与合同制开发服务。","milestones.freelance.highlight_0.label":"客户交付","milestones.freelance.highlight_0.text":"交付了40多个国际 Vue/React 项目（SaaS、电商），准时交付率达100%，客户评分5.0，负责从客户接洽到上线的完整SDLC，包括复杂的第三方API集成。","proof_items.0.label":"教育背景","proof_items.0.value":"信息系统专业","proof_items.0.note":"苏莱曼·德米雷尔大学 · 2018–2022 · GPA 3.72 / 4.0","proof_items.1.label":"英语","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"学术类雅思 · CEFR C1 水平","proof_items.2.label":"获奖","proof_items.2.value":"银牌","proof_items.2.note":"Infomatrix Asia-Pacific 2018 —— 国际计算机项目竞赛。","proof_items.3.label":"推荐","proof_items.3.value":"KeyHorse","proof_items.3.note":"来自公司管理层签署的推荐信","proof_items.4.label":"语言能力","proof_items.4.value":"5 门语言","proof_items.4.note":"英语——熟练的工作水平 · 哈萨克语和俄语——母语 · 土耳其语——日常会话水平 · 汉语——基础水平","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"学术类雅思成绩（CEFR C1）——证明具备胜任国际化、远程优先工程岗位所需的全面专业英语能力。","proof_documents.chinese-proficiency.title":"中文水平证明","proof_documents.chinese-proficiency.description":"在与跨境产品及业务团队的专业合作中同步培养起来的基础中文水平。","proof_documents.infomatrix.title":"银牌——Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"早期一个软件工程项目在国际计算机项目竞赛中获得的认可。","proof_documents.keyhorse.title":"推荐信——KeyHorse","proof_documents.keyhorse.description":"一封使用 KeyHorse official 信头、已签署的推荐信，推荐 Zhassulan 担任高级工程岗位。","projects.geonomix.description":"一个大型地理信息与数字孪生平台，在区域部署中整合了交互式地图、市政数据、数字登记系统、政务服务与监控工具。","projects.midas-event.description":"一个活动策划公司的网站，被设计成可浏览的往期活动作品集，而非静态服务列表，通篇采用 React 打造的交互式细节展示。","projects.kostyum.description":"一个响应式男装电商前端，具备可复用的商品目录 UI，专注于在桌面端与移动端提供流畅的购物体验。","projects.unistory.description":"一个数字产品界面，将加密钱包状态和异步后端数据整合进可复用的 React 产品组件中。","projects.kazmed.description":"为一家获授权的医疗设备服务合作伙伴打造的企业前端，围绕基于 Swiper 的设备与服务目录构建，而非冗长的文字页面。","projects.dostyk-trans-terminal.description":"一个位于多斯特克—阿拉山口口岸的物流枢纽企业网站，展示集装箱装卸、仓储与转运服务。","projects.melissa.description":"一家拥有 13,000 多种商品的大型在线药店，包含目录导航、搜索、筛选、排序、商品页面、购物车流程及后端集成。","projects.abi-construction.description":"一家建筑公司的网站，将 WordPress 内容后台与基于 Vue 构建的交互式项目展示画廊结合在一起。","projects.tahit.description":"一家制造企业的前端，在桌面端与移动端展示其纺织生产能力、技术、产品与服务。","projects.dobraya.description":"一个在线药店的前台展示页面，具备响应式目录、分类导航、搜索、筛选与下单流程。","projects.asia-mebel.description":"一个家具材料、五金配件、工具与相关服务的商用目录，具有结构化导航、筛选、搜索与商品页面。","projects.pharmacom.description":"为一家疫苗接种诊所及药店网络打造的医疗健康网站，围绕门店位置、服务项目与患者信息组织内容，而非单一的静态首页。","projects.navat.description":"一个餐厅宣传落地页，围绕菜单、氛围与品牌形象打造出响应式的视觉体验。","projects.asia-credit-bank.description":"一个银行客服中心网站，把大量产品与支持类页面整合成快速、易于浏览的结构，方便客户查找信息。","projects.geonomix.note":"一个以地图为核心的产品，数据体量与可复用的区域化交付方式共同决定了前端架构。","projects.melissa.note":"一个大型商品目录场景，信息架构的重要性不亚于界面打磨本身。"},m={"signals.0.label":"jaar in productie-ontwikkeling","signals.0.note":"Van een React-stage tot senior verantwoordelijkheid in internationale productteams.","signals.1.label":"gebruikers","signals.1.note":"Productie-interfaces die draaien op een schaal die van belang is voor het bedrijf.","signals.2.label":"opgeleverde projecten","signals.2.note":"Web-, mobiele en data-intensieve platforms.","signals.3.label":"geoptimaliseerde projecten","signals.3.note":"Verbeteringen in performance, architectuur en onderhoudbaarheid.","case_studies.01.kicker":"Architectuur op productschaal","case_studies.01.title":"Tien modules tot één systeem maken.","case_studies.01.problem":"Een groeiend Vue-productoppervlak moest consistent blijven terwijl 10+ modules parallel evolueerden voor een platform met meer dan een miljoen gebruikers per jaar.","case_studies.01.solution":"Ik definieerde herbruikbare Vue 3/TypeScript-patronen voor composition, routing, state en gedeelde productscenario’s, zodat nieuwe features starten vanuit een kant-en-klaar systeem in plaats van lokale afspraken.","case_studies.01.result":"De architectuur verkortte de implementatietijd van features met ongeveer 30% en legde een steviger fundament voor ontwikkeling tussen modules.","case_studies.01.metrics.0.label":"productmodules","case_studies.01.metrics.1.label":"snellere feature-levering","case_studies.02.kicker":"Performance als architectuur","case_studies.02.title":"Laadtijd behandelen als een graaf, niet als een getal.","case_studies.02.problem":"Zwaarbelaste schermen werden trager door werk dat verspreid was over rendering, data-ophaling, caching en asynchrone UI-stromen — niet door één duidelijk knelpunt.","case_studies.02.solution":"Ik optimaliseerde het volledige pad van aanvraag tot rendering: renderinggedrag, caching, asynchrone orkestratie en API-verzoekpatronen, ondersteund door Core Web Vitals, Lighthouse, tests en Sentry-monitoring.","case_studies.02.result":"De gemiddelde paginalaadtijd daalde van ongeveer 3,2 naar 2,1 seconden, terwijl het platform bleef groeien.","case_studies.02.metrics.0.label":"gemiddelde laadtijd","case_studies.02.metrics.1.label":"geschatte afname","case_studies.03.kicker":"Geodata-performance","case_studies.03.title":"Een half miljoen kaartobjecten moeten interactief blijven.","case_studies.03.problem":"Dichte GIS-interfaces moesten datasets van ongeveer 300.000–500.000 geo-objecten renderen en verwerken zonder de eerste interactie merkbaar te vertragen.","case_studies.03.solution":"Ik bouwde lagen en stijlen opnieuw op, introduceerde client-side clustering en filtering, en verminderde overbodig werk in het Vuex-Elasticsearch-datapad.","case_studies.03.result":"De initiële rendering van Mapbox GL JS daalde van ongeveer 800 naar 480 ms, en apart algoritmewerk leverde een verbetering van 30% in geo-zoeksnelheid op.","case_studies.03.metrics.0.label":"initiële kaartrendering","case_studies.03.metrics.1.label":"geo-objecten","case_studies.04.kicker":"Herbruikbare leversystemen","case_studies.04.title":"Het volgende regionale product samenstellen uit configuratie, niet door te kopiëren.","case_studies.04.problem":"Tientallen regionale GIS-producten herhaalden dezelfde UI- en datapatronen, maar herimplementatie vertraagde de levering en maakte consistentie duurder.","case_studies.04.solution":"Ik bouwde een gecentraliseerde architectuur met 100+ herbruikbare Vue-componenten en gedeelde modules, en standaardiseerde daarop BEM, theming, rolpatronen, linting en testpraktijken.","case_studies.04.result":"Een vergelijkbare implementatie kostte tot 50% minder tijd; sommige lanceringen die eerder ongeveer een maand kostten, pasten nu in ongeveer een week.","case_studies.04.metrics.0.label":"herbruikbare componenten","case_studies.04.metrics.1.label":"vergelijkbare implementaties","surfaces.A.title":"Zwaarbelaste productmodules","surfaces.A.text":"Interfaces waar architectuur, caching, state en API-gedrag moeten functioneren als één productsysteem.","surfaces.B.title":"Geospatiale systemen","surfaces.B.text":"Kaartrijke producten waar het datavolume de frontend-architectuur zelf vormt, niet alleen de renderlaag.","surfaces.C.title":"Moderniseringsprogramma’s","surfaces.C.text":"De overgang van legacy naar een moderne stack zonder de productlevering te stoppen terwijl de technische basis verandert.","surfaces.D.title":"End-to-end productlevering","surfaces.D.text":"Frontend-engineering met genoeg backend-diepgang om API’s, integratiegrenzen en productiegedrag te beheren.","principles.01.title":"Eerst meten, dan herschrijven.","principles.01.text":"Een performanceverandering moet beginnen met feiten en eindigen met een resultaat dat de gebruiker merkt.","principles.02.title":"Architectuur is een leverinstrument.","principles.02.text":"De beste abstractie is degene die de volgende feature goedkoper, veiliger en begrijpelijker maakt.","principles.03.title":"Frontend is onderdeel van het systeem.","principles.03.text":"Rendering, datavorm, API’s, toegankelijkheid, observability en release-pipelines zijn één technisch geheel.","principles.04.title":"Senior zijn betekent onzekerheid verminderen.","principles.04.text":"Technisch leiderschap betekent afwegingen zichtbaar maken zodat het team snel vooruit kan zonder verborgen risico’s op te bouwen.","milestones.ciklum.role":"Senior Software Engineer","milestones.ciklum.focus":"Frontend-architectuur · productmodernisering · performance · technisch leiderschap","milestones.keyhorse.role":"Middle → Senior → Team Lead Software Engineer","milestones.keyhorse.focus":"GIS · digital twins · technisch leiderschap · herbruikbare systemen · backend-API’s","milestones.dar.role":"Junior Software Engineer","milestones.dar.focus":"Hoogvolume webontwikkeling · e-commerce · mobiele apps · performance","milestones.epam.role":"Software Engineer Stagiair","milestones.epam.focus":"React · TypeScript · herbruikbare UI · technische basis","milestones.freelance.role":"Freelance Software Engineer","milestones.freelance.focus":"Freelance Vue/React-ontwikkeling · end-to-end levering van SaaS & e-commerce · klantbeheer","milestones.ciklum.location":"Boekarest, Roemenië (op afstand)","milestones.ciklum.summary":"Wereldwijde leider in digitale producten en transformatie van bedrijfssoftware, gevestigd in het VK.","milestones.ciklum.highlight_0.label":"Architectuur","milestones.ciklum.highlight_0.text":"Bouwde een gedeelde Vue 3/strict-TypeScript-componentenbibliotheek en een type-veilige REST/GraphQL-API-laag voor 10+ modules (1–3 miljoen gebruikers), gebouwd volgens de WCAG AA-standaard — verkortte de implementatietijd van features met ~30%.","milestones.ciklum.highlight_1.label":"Technisch Leiderschap","milestones.ciklum.highlight_1.text":"Nam frontend-architectuurbeslissingen en leidde sprintplanning en backlog-verfijning voor een team van 6 engineers; voerde wekelijks ~15 GitLab merge-request-reviews uit en verlaagde post-merge-defecten met 35%.","milestones.ciklum.highlight_2.label":"Performance & Core Web Vitals","milestones.ciklum.highlight_2.text":"Optimaliseerde rendering-, caching- en netwerkverzoekpatronen voor drukbezochte modules, verlaagde de interactielatentie (INP) van ~280ms naar ~150ms en verminderde dubbele API-aanroepen met 40%.","milestones.ciklum.highlight_3.label":"Modernisering & Betrouwbaarheid","milestones.ciklum.highlight_3.text":"Moderniseerde legacy Vue 2-codebases naar Vue 3, Composition API, Pinia en Vite, verkleinde de bundle-grootte met 20%; versterkte de betrouwbaarheid met Vitest/Jest-tests, Sentry-monitoring en CI/CD-workflows.","milestones.ciklum.highlight_4.label":"Tooling, Mobile & AI","milestones.ciklum.highlight_4.text":"Structureerde codebases met Feature-Sliced Design en TanStack Query, verminderde boilerplate met ~25%; breidde het designsysteem uit naar een Ionic/Capacitor mobiele app en implementeerde AI-ondersteunde ontwikkeltools (Cursor, Claude Code).","milestones.keyhorse.location":"Almaty, Kazachstan","milestones.keyhorse.summary":"Bedrijf voor GIS- en digital-twin-platforms, actief in Centraal-Azië.","milestones.keyhorse.roles.team-lead.label":"Team Lead","milestones.keyhorse.roles.team-lead.highlight_0.label":"Technisch Leiderschap","milestones.keyhorse.roles.team-lead.highlight_0.text":"Leidde een engineeringafdeling van 18 developers verdeeld over 3 subteams, gaf leiding aan de overstap naar Scrum en bepaalde de technische richting voor de levering van 80+ grootschalige regionale en 100+ kleinere digital-twin-projecten voor 1,5 miljoen+ actieve gebruikers in 4 landen.","milestones.keyhorse.roles.team-lead.highlight_1.label":"Zelfstandige Productlevering","milestones.keyhorse.roles.team-lead.highlight_1.text":"Ontwierp en lanceerde zelfstandig 10 enterprise-platforms vanaf nul, elk binnen 1–1,5 maand, en verkortte de time-to-market ~2x ten opzichte van het historische gemiddelde van het bedrijf.","milestones.keyhorse.roles.team-lead.highlight_2.label":"Proces & Governance","milestones.keyhorse.roles.team-lead.highlight_2.text":"Leidde sprintplanning, inschatting en technische documentatie, voerde wekelijks ~50 code reviews uit en stelde documentatiestandaarden op die de inwerktijd van nieuwe medewerkers met 40% verkortten.","milestones.keyhorse.roles.mid-senior.label":"Middle → Senior","milestones.keyhorse.roles.mid-senior.highlight_0.label":"Geospatiale Performance","milestones.keyhorse.roles.mid-senior.highlight_0.text":"Verlaagde de Mapbox GL JS-rendertijd met 40% (800ms → 480ms) en herstructureerde Elasticsearch-indexerings-/queryreactiepatronen met gememoriseerde Vuex-getters, waardoor de zoeklatentie met 30% daalde over 500K+ geo-objecten.","milestones.keyhorse.roles.mid-senior.highlight_1.label":"Frontend-architectuur","milestones.keyhorse.roles.mid-senior.highlight_1.text":"Ontwierp een gedeelde Vue-architectuur (100+ FSD-componenten), gedocumenteerd in een gedeelde Storybook-componentenbibliotheek om UI-patronen tussen teams te standaardiseren — verkortte de ontwikkelcyclus van features met 50%.","milestones.keyhorse.roles.mid-senior.highlight_2.label":"Backend & Datamodellering","milestones.keyhorse.roles.mid-senior.highlight_2.text":"Bouwde 35+ Django/PostgreSQL REST-endpoints met Redis-caching en geoptimaliseerde PL/pgSQL-stored procedures voor grootschalige geospatiale datasets, met behoud van 99,9% productie-uptime tijdens het genereren van type-veilige API-clients voor frontend-integratie.","milestones.keyhorse.roles.mid-senior.highlight_3.label":"DevOps & Automatisering","milestones.keyhorse.roles.mid-senior.highlight_3.text":"Ontwierp een Vitest-, Playwright- en Cypress-teststrategie en handhaafde productiekwaliteitspoorten via uniforme GitLab CI/CD-pipelines voor 86 repositories, verhoogde de codedekking naar 70–80% en verminderde regressiebugs met 30%.","milestones.keyhorse.roles.mid-senior.highlight_4.label":"Designsystemen & WCAG","milestones.keyhorse.roles.mid-senior.highlight_4.text":"Ontwikkelde een CSS-framework met design tokens, SCSS en BEM-methodologie volgens de WCAG AA-standaard, waardoor de implementatietijd van UI daalde van ~3 dagen naar ~4 uur.","milestones.dar.summary":"Technologiegroep die digitale producten en platforms ontwikkelt in fintech, onderwijs, sport en bedrijfsvoering.","milestones.dar.highlight_0.label":"Productiearchitectuur","milestones.dar.highlight_0.text":"Leverde 30+ meerpagina-productieapplicaties (elk 8+ pagina’s) terwijl tot 3–4 gelijktijdige projecten werden beheerd, verkortte de levertijd met 25% (5–10 dagen per cyclus) dankzij een herbruikbare Vue/React-componentenbibliotheek (34 componenten, BEM-architectuur).","milestones.dar.highlight_1.label":"Platformlevering","milestones.dar.highlight_1.text":"Ontwierp en lanceerde zelfstandig twee volwaardige platforms — voedselbezorging en accommodatieboeking — elk binnen ~1 maand, inclusief GSAP-gedreven animaties, ten behoeve van 150–200 restaurants in 3 steden en 100–150 vastgoedvermeldingen.","milestones.dar.highlight_2.label":"Performance & SEO","milestones.dar.highlight_2.text":"Verlaagde laadtijden met 40% (naar 1,8–2,2s) via SSR, code splitting, lazy loading en bundle-optimalisatie, en behaalde bij de meeste projecten een Lighthouse SEO-score van 100/100.","milestones.dar.highlight_3.label":"Cross-platform Ontwikkeling","milestones.dar.highlight_3.text":"Bracht 5–7 productie-mobiele apps (iOS/Android) uit met Ionic, Capacitor en React Native, met 40–50% gedeelde code tussen platforms.","milestones.dar.highlight_4.label":"Backend & API’s","milestones.dar.highlight_4.text":"Bouwde en onderhield Laravel/MySQL REST-backends — API-ontwerp, databaseschema en authenticatie — voor 6 van deze applicaties, goed voor 15K+ verzoeken per dag.","milestones.epam.summary":"Wereldwijd IT-adviesbureau en digital-engineeringbedrijf.","milestones.epam.highlight_0.label":"Competitieve Selectie","milestones.epam.highlight_0.text":"Geselecteerd als 1 van 3 aangenomen engineers uit 40+ sollicitanten in een competitief technisch wervingsproces.","milestones.epam.highlight_1.label":"Frontend-ontwikkeling","milestones.epam.highlight_1.text":"Bouwde responsieve React/TypeScript-interfaces en herbruikbare componentenbibliotheken, integreerde API’s in productieworkflows; droeg bij aan 5+ interne bedrijfstools.","milestones.epam.highlight_2.label":"Professionele Groei","milestones.epam.highlight_2.text":"Nam deel aan code reviews, unit tests en leveringsstandaarden op enterprise-niveau — een basis die in elke volgende rol werd meegenomen.","milestones.freelance.location":"Op afstand (internationale klanten)","milestones.freelance.summary":"Zelfstandig freelance- en contractwerk voor internationale klanten, naast voltijdse functies.","milestones.freelance.highlight_0.label":"Klantoplevering","milestones.freelance.highlight_0.text":"Leverde 40+ internationale Vue/React-projecten (SaaS, e-commerce) met een 100% tijdige oplevering en een 5.0-beoordeling, verantwoordelijk voor de volledige SDLC van klantacquisitie tot productie, inclusief complexe integraties met externe API's.","proof_items.0.label":"Opleiding","proof_items.0.value":"Informatiesystemen","proof_items.0.note":"Suleyman Demirel University · 2018–2022 · GPA 3,72/4,0","proof_items.1.label":"Engels","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"Academic IELTS · CEFR C1-resultaat","proof_items.2.label":"Erkenning","proof_items.2.value":"Zilveren medaille","proof_items.2.note":"Infomatrix Asia-Pacific 2018 — internationale computerprojectwedstrijd.","proof_items.3.label":"Aanbeveling","proof_items.3.value":"KeyHorse","proof_items.3.note":"Ondertekende aanbeveling van het bedrijfsmanagement","proof_items.4.label":"Talen","proof_items.4.value":"5 talen","proof_items.4.note":"Engels — uitstekend zakelijk niveau · Kazachs & Russisch — moedertaal · Turks — conversatieniveau · Chinees — basisniveau","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"Resultaat van de Academic IELTS (CEFR C1) — bewijs van vloeiend, professioneel Engels voor internationale, remote-first engineeringfuncties.","proof_documents.chinese-proficiency.title":"Chinese taalvaardigheid","proof_documents.chinese-proficiency.description":"Basiskennis van het Chinees, ontwikkeld naast professioneel werk met grensoverschrijdende product- en businessteams.","proof_documents.infomatrix.title":"Zilveren medaille — Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"Erkenning bij een internationale computerprojectwedstrijd voor een van zijn vroege technische werken.","proof_documents.keyhorse.title":"Aanbevelingsbrief — KeyHorse","proof_documents.keyhorse.description":"Ondertekende aanbeveling op briefpapier van KeyHorse, waarin Zhassulan wordt aanbevolen voor een senior engineering-functie.","projects.geonomix.description":"Grootschalig geospatiaal platform en digital twin dat interactieve kaarten, gemeentelijke data, digitale registers, overheidsdiensten en monitoringtools combineert in regionale implementaties.","projects.midas-event.description":"Website van een eventbureau, opgebouwd als een doorbladerbaar portfolio van eerdere evenementen in plaats van een statische dienstenlijst, met interactieve details in React.","projects.kostyum.description":"Responsief e-commerce-frontend voor herenmode met herbruikbare productcatalogus-UI en focus op een soepele winkelervaring op desktop en mobiel.","projects.unistory.description":"Digitale productinterface die crypto-wallet-status en asynchrone backend-data integreert in herbruikbare React-productcomponenten.","projects.kazmed.description":"Zakelijk frontend voor een erkende servicepartner voor medische apparatuur, opgebouwd rond een Swiper-catalogus in plaats van lange tekstpagina’s.","projects.dostyk-trans-terminal.description":"Zakelijke website voor een logistiek terminal bij de grensovergang Dostyk–Alashankou, met diensten voor containeroverslag, opslag en doorvoer.","projects.melissa.description":"Grote online apotheek met meer dan 13.000 producten, inclusief catalogusnavigatie, zoeken, filteren, sorteren, productpagina’s, winkelwagen en backend-integraties.","projects.abi-construction.description":"Website van een bouwbedrijf die een WordPress CMS-backend combineert met interactieve projectgalerijen in Vue.","projects.tahit.description":"Frontend van een productiebedrijf dat textielproductiecapaciteit, technologie, producten en diensten toont op desktop en mobiel.","projects.dobraya.description":"Etalage van een online apotheek met responsieve catalogi, categorienavigatie, zoeken, filteren en afrekenstromen.","projects.asia-mebel.description":"Commerciële catalogus voor meubelmaterialen, beslag, gereedschap en diensten met gestructureerde navigatie, filtering, zoeken en productpagina’s.","projects.pharmacom.description":"Website voor een netwerk van vaccinatieklinieken en apotheken, georganiseerd rond locaties, diensten en patiënteninformatie in plaats van één statische homepage.","projects.navat.description":"Promotionele landingspagina voor een restaurant met een responsieve visuele ervaring rond menu, sfeer en merk.","projects.asia-credit-bank.description":"Website van het klantcontactcentrum van een bank die een grote verzameling product- en supportpagina’s omzet in een snelle, gemakkelijk navigeerbare structuur.","projects.geonomix.note":"Een product waarbij de kaart centraal staat en datavolume plus herbruikbare regionale levering de frontend-architectuur bepaalden.","projects.melissa.note":"Ervaring met een grote catalogus waarbij informatiearchitectuur net zo belangrijk is als UI-polish."},d={"signals.0.label":"Jahre in der Produktentwicklung","signals.0.note":"Vom React-Praktikum bis zur Senior-Verantwortung in internationalen Produktteams.","signals.1.label":"Nutzer","signals.1.note":"Produktions-Interfaces, die in einem für das Geschäft relevanten Maßstab laufen.","signals.2.label":"ausgelieferte Projekte","signals.2.note":"Web-, Mobile- und datenintensive Plattformen.","signals.3.label":"optimierte Projekte","signals.3.note":"Verbesserungen bei Performance, Architektur und Wartbarkeit.","case_studies.01.kicker":"Architektur im Produktmaßstab","case_studies.01.title":"Zehn Module zu einem System machen.","case_studies.01.problem":"Eine wachsende Vue-Produktoberfläche musste konsistent bleiben, während sich 10+ Module parallel für eine Plattform mit über einer Million Nutzern pro Jahr weiterentwickelten.","case_studies.01.solution":"Ich definierte wiederverwendbare Vue 3/TypeScript-Muster für Composition, Routing, State und gemeinsame Produktszenarien, damit neue Features von einem fertigen System statt von lokalen Absprachen ausgehen.","case_studies.01.result":"Die Architektur senkte die Umsetzungszeit für Features um etwa 30 % und schuf eine solidere Basis für die modulübergreifende Entwicklung.","case_studies.01.metrics.0.label":"Produktmodule","case_studies.01.metrics.1.label":"schnellere Feature-Auslieferung","case_studies.02.kicker":"Performance als Architektur","case_studies.02.title":"Ladezeit als Graph behandeln, nicht als Zahl.","case_studies.02.problem":"Stark frequentierte Bildschirme wurden langsamer durch Arbeit, die über Rendering, Datenabruf, Caching und asynchrone UI-Abläufe verteilt war — nicht durch einen einzelnen offensichtlichen Engpass.","case_studies.02.solution":"Ich optimierte den gesamten Weg von der Anfrage bis zum Rendern: Rendering-Verhalten, Caching, asynchrone Orchestrierung und API-Anfragemuster, abgesichert durch Core Web Vitals, Lighthouse, Tests und Sentry-Monitoring.","case_studies.02.result":"Die durchschnittliche Seitenladezeit sank von etwa 3,2 auf 2,1 Sekunden, während sich die Plattform weiterentwickelte.","case_studies.02.metrics.0.label":"durchschnittliche Ladezeit","case_studies.02.metrics.1.label":"ungefähre Reduzierung","case_studies.03.kicker":"Geodaten-Performance","case_studies.03.title":"Eine halbe Million Kartenobjekte müssen interaktiv bleiben.","case_studies.03.problem":"Dichte GIS-Interfaces mussten Datensätze von etwa 300.000–500.000 Geo-Objekten rendern und verarbeiten, ohne die erste Interaktion spürbar zu verlangsamen.","case_studies.03.solution":"Ich baute Layer und Styles neu auf, führte clientseitiges Clustering und Filtern ein und reduzierte überflüssige Arbeit im Vuex-Elasticsearch-Datenpfad.","case_studies.03.result":"Das initiale Rendering von Mapbox GL JS fiel von etwa 800 auf 480 ms, zusätzlich brachte separate Algorithmusarbeit eine 30%ige Verbesserung der Geosuche-Geschwindigkeit.","case_studies.03.metrics.0.label":"initiales Karten-Rendering","case_studies.03.metrics.1.label":"Geo-Objekte","case_studies.04.kicker":"Wiederverwendbare Liefersysteme","case_studies.04.title":"Das nächste regionale Produkt aus Konfiguration statt Kopieren zusammensetzen.","case_studies.04.problem":"Dutzende regionale GIS-Produkte wiederholten dieselben UI- und Datenmuster, aber die erneute Implementierung verlangsamte die Lieferung und verteuerte die Konsistenz.","case_studies.04.solution":"Ich schuf eine zentralisierte Architektur mit 100+ wiederverwendbaren Vue-Komponenten und gemeinsamen Modulen und standardisierte darauf aufbauend BEM, Theming, Rollenmuster, Linting und Testpraktiken.","case_studies.04.result":"Eine ähnliche Implementierung dauerte bis zu 50 % weniger Zeit; manche Einführungen, die früher etwa einen Monat dauerten, passten nun in etwa eine Woche.","case_studies.04.metrics.0.label":"wiederverwendbare Komponenten","case_studies.04.metrics.1.label":"ähnliche Implementierungen","surfaces.A.title":"Stark frequentierte Produktmodule","surfaces.A.text":"Interfaces, bei denen Architektur, Caching, State und API-Verhalten als ein einziges Produktsystem funktionieren müssen.","surfaces.B.title":"Geodatensysteme","surfaces.B.text":"Kartenreiche Produkte, bei denen das Datenvolumen die Frontend-Architektur selbst prägt, nicht nur die Rendering-Ebene.","surfaces.C.title":"Modernisierungsprogramme","surfaces.C.text":"Der Übergang von Legacy zu einem modernen Stack, ohne die Produktlieferung zu stoppen, während sich das technische Fundament ändert.","surfaces.D.title":"End-to-End-Produktlieferung","surfaces.D.text":"Frontend-Engineering mit genug Backend-Tiefe, um APIs, Integrationsgrenzen und Produktionsverhalten zu verantworten.","principles.01.title":"Erst messen, dann umschreiben.","principles.01.text":"Eine Performance-Änderung sollte mit Fakten beginnen und mit einem für Nutzer spürbaren Ergebnis enden.","principles.02.title":"Architektur ist ein Lieferwerkzeug.","principles.02.text":"Die beste Abstraktion ist die, die das nächste Feature günstiger, sicherer und verständlicher macht.","principles.03.title":"Frontend ist Teil des Systems.","principles.03.text":"Rendering, Datenform, APIs, Barrierefreiheit, Observability und Release-Pipelines sind eine einzige technische Oberfläche.","principles.04.title":"Senior zu sein heißt, Unsicherheit zu reduzieren.","principles.04.text":"Technische Führung bedeutet, Kompromisse sichtbar zu machen, damit das Team schnell vorankommt, ohne verborgene Risiken anzuhäufen.","milestones.ciklum.role":"Senior Software Engineer","milestones.ciklum.focus":"Frontend-Architektur · Produktmodernisierung · Performance · technische Führung","milestones.keyhorse.role":"Middle → Senior → Team Lead Software Engineer","milestones.keyhorse.focus":"GIS · digitale Zwillinge · technische Führung · wiederverwendbare Systeme · Backend-APIs","milestones.dar.role":"Junior Software Engineer","milestones.dar.focus":"Hochvolumige Webentwicklung · E-Commerce · mobile Apps · Performance","milestones.epam.role":"Software Engineer Praktikant","milestones.epam.focus":"React · TypeScript · wiederverwendbares UI · technische Grundlagen","milestones.freelance.role":"Freelance Software Engineer","milestones.freelance.focus":"Freelance Vue/React-Entwicklung · End-to-End-Lieferung von SaaS & E-Commerce · Kundenmanagement","milestones.ciklum.location":"Bukarest, Rumänien (Remote)","milestones.ciklum.summary":"Global tätiger Anbieter für digitale Produkte und Unternehmenssoftware-Transformation mit Sitz im Vereinigten Königreich.","milestones.ciklum.highlight_0.label":"Architektur","milestones.ciklum.highlight_0.text":"Etablierte eine gemeinsame Vue 3/strict-TypeScript-Komponentenbibliothek und eine typsichere REST/GraphQL-API-Schicht über 10+ Module (1–3 Mio. Nutzer) hinweg, nach WCAG-AA-Standard gebaut — senkte die Umsetzungszeit für Features um ~30 %.","milestones.ciklum.highlight_1.label":"Technische Führung","milestones.ciklum.highlight_1.text":"Traf Frontend-Architekturentscheidungen und leitete Sprint-Planung sowie Backlog-Pflege für ein Team von 6 Ingenieuren; führte ~15 GitLab-Merge-Request-Reviews pro Woche durch und senkte Post-Merge-Fehler um 35 %.","milestones.ciklum.highlight_2.label":"Performance & Core Web Vitals","milestones.ciklum.highlight_2.text":"Optimierte Rendering-, Caching- und Netzwerkanfragemuster über stark frequentierte Module hinweg, senkte die Interaktionslatenz (INP) von ~280 ms auf ~150 ms und reduzierte doppelte API-Aufrufe um 40 %.","milestones.ciklum.highlight_3.label":"Modernisierung & Zuverlässigkeit","milestones.ciklum.highlight_3.text":"Modernisierte Legacy-Vue-2-Codebasen zu Vue 3, Composition API, Pinia und Vite, verkleinerte die Bundle-Größe um 20 %; stärkte die Zuverlässigkeit durch Vitest/Jest-Tests, Sentry-Monitoring und CI/CD-Workflows.","milestones.ciklum.highlight_4.label":"Tooling, Mobile & KI","milestones.ciklum.highlight_4.text":"Strukturierte Codebasen mit Feature-Sliced Design und TanStack Query, reduzierte Boilerplate um ~25 %; erweiterte das Designsystem auf eine Ionic/Capacitor-Mobile-App und führte KI-gestützte Entwicklungstools (Cursor, Claude Code) ein.","milestones.keyhorse.location":"Almaty, Kasachstan","milestones.keyhorse.summary":"Unternehmen für GIS- und Digital-Twin-Plattformen mit Fokus auf Zentralasien.","milestones.keyhorse.roles.team-lead.label":"Team Lead","milestones.keyhorse.roles.team-lead.highlight_0.label":"Technische Führung","milestones.keyhorse.roles.team-lead.highlight_0.text":"Leitete eine Engineering-Abteilung mit 18 Entwicklern in 3 Teilteams, führte den Wechsel zu Scrum an und gab die technische Richtung für 80+ groß angelegte regionale und 100+ kleinere Digital-Twin-Projekte für 1,5 Mio.+ aktive Nutzer in 4 Ländern vor.","milestones.keyhorse.roles.team-lead.highlight_1.label":"Eigenständige Produktentwicklung","milestones.keyhorse.roles.team-lead.highlight_1.text":"Konzipierte und launchte eigenständig 10 Unternehmensplattformen von Grund auf in jeweils 1–1,5 Monaten und verkürzte die Time-to-Market im Vergleich zum historischen Durchschnitt des Unternehmens um ~das Doppelte.","milestones.keyhorse.roles.team-lead.highlight_2.label":"Prozesse & Governance","milestones.keyhorse.roles.team-lead.highlight_2.text":"Leitete Sprint-Planung, Schätzungen und technische Dokumentation, führte ~50 Code-Reviews pro Woche durch und etablierte Dokumentationsstandards, die die Einarbeitungszeit neuer Mitarbeiter um 40 % verkürzten.","milestones.keyhorse.roles.mid-senior.label":"Middle → Senior","milestones.keyhorse.roles.mid-senior.highlight_0.label":"Geodaten-Performance","milestones.keyhorse.roles.mid-senior.highlight_0.text":"Reduzierte die Mapbox-GL-JS-Renderzeit um 40 % (800 ms → 480 ms) und strukturierte Elasticsearch-Indizierungs-/Abfragemuster mit memoisierten Vuex-Gettern neu, wodurch die Suchlatenz bei 500.000+ Geo-Objekten um 30 % sank.","milestones.keyhorse.roles.mid-senior.highlight_1.label":"Frontend-Architektur","milestones.keyhorse.roles.mid-senior.highlight_1.text":"Entwarf eine gemeinsame Vue-Architektur (100+ FSD-Komponenten), dokumentiert in einer Storybook-Komponentenbibliothek zur Standardisierung von UI-Mustern teamübergreifend — verkürzte den Feature-Entwicklungszyklus um 50 %.","milestones.keyhorse.roles.mid-senior.highlight_2.label":"Backend & Datenmodellierung","milestones.keyhorse.roles.mid-senior.highlight_2.text":"Entwickelte 35+ Django/PostgreSQL-REST-Endpunkte mit Redis-Caching und optimierten PL/pgSQL-Stored-Procedures für großangelegte Geodatensätze, hielt dabei 99,9 % Produktions-Uptime bei gleichzeitiger Generierung typsicherer API-Clients für die Frontend-Integration.","milestones.keyhorse.roles.mid-senior.highlight_3.label":"DevOps & Automatisierung","milestones.keyhorse.roles.mid-senior.highlight_3.text":"Entwarf eine Vitest-, Playwright- und Cypress-Teststrategie und setzte Production-Quality-Gates über einheitliche GitLab-CI/CD-Pipelines in 86 Repositories durch, erhöhte die Codeabdeckung auf 70–80 % und senkte Regressionsfehler um 30 %.","milestones.keyhorse.roles.mid-senior.highlight_4.label":"Designsysteme & WCAG","milestones.keyhorse.roles.mid-senior.highlight_4.text":"Entwickelte ein CSS-Framework mit Design-Tokens, SCSS und BEM-Methodik nach WCAG-AA-Standard, das die UI-Umsetzungszeit von ~3 Tagen auf ~4 Stunden reduzierte.","milestones.dar.summary":"Technologiegruppe, die digitale Produkte und Plattformen in den Bereichen Fintech, Bildung, Sport und Geschäftsbetrieb entwickelt.","milestones.dar.highlight_0.label":"Produktionsarchitektur","milestones.dar.highlight_0.text":"Lieferte 30+ mehrseitige Produktionsanwendungen (je 8+ Seiten) bei gleichzeitiger Betreuung von bis zu 3–4 parallelen Projekten und verkürzte die Lieferzeit um 25 % (5–10 Tage/Zyklus) durch eine wiederverwendbare Vue/React-Komponentenbibliothek (34 Komponenten, BEM-Architektur).","milestones.dar.highlight_1.label":"Plattformentwicklung","milestones.dar.highlight_1.text":"Konzipierte und launchte eigenständig zwei vollwertige Plattformen — Essenslieferung und Unterkunftsbuchung — in jeweils ~1 Monat, inklusive GSAP-gestützter Animationen, für 150–200 Restaurants in 3 Städten und 100–150 Immobilienanzeigen.","milestones.dar.highlight_2.label":"Performance & SEO","milestones.dar.highlight_2.text":"Senkte Ladezeiten um 40 % (auf 1,8–2,2 s) durch SSR, Code-Splitting, Lazy Loading und Bundle-Optimierung, erreichte bei den meisten Projekten 100/100 im Lighthouse-SEO-Score.","milestones.dar.highlight_3.label":"Plattformübergreifende Entwicklung","milestones.dar.highlight_3.text":"Veröffentlichte 5–7 Produktions-Mobile-Apps (iOS/Android) mit Ionic, Capacitor und React Native, mit 40–50 % gemeinsam genutztem Code über Plattformen hinweg.","milestones.dar.highlight_4.label":"Backend & APIs","milestones.dar.highlight_4.text":"Entwickelte und pflegte Laravel/MySQL-REST-Backends — API-Design, Datenbankschema und Authentifizierung — für 6 dieser Anwendungen mit 15.000+ Anfragen pro Tag.","milestones.epam.summary":"Global tätiges IT-Beratungs- und Digital-Engineering-Unternehmen.","milestones.epam.highlight_0.label":"Wettbewerbsauswahl","milestones.epam.highlight_0.text":"Als einer von 3 Ingenieuren aus 40+ Bewerbern in einem wettbewerbsorientierten technischen Auswahlverfahren ausgewählt.","milestones.epam.highlight_1.label":"Frontend-Entwicklung","milestones.epam.highlight_1.text":"Entwickelte responsive React/TypeScript-Oberflächen und wiederverwendbare Komponentenbibliotheken, integrierte APIs in Produktions-Workflows; trug zu 5+ internen Unternehmenstools bei.","milestones.epam.highlight_2.label":"Fachliches Wachstum","milestones.epam.highlight_2.text":"Nahm an Code-Reviews, Unit-Tests und Lieferstandards auf Enterprise-Niveau teil — eine Grundlage, die in jede folgende Rolle mitgenommen wurde.","milestones.freelance.location":"Remote (internationale Kunden)","milestones.freelance.summary":"Unabhängige freiberufliche und projektbasierte Arbeit für internationale Kunden, parallel zu Vollzeitpositionen.","milestones.freelance.highlight_0.label":"Kundenprojekte","milestones.freelance.highlight_0.text":"Lieferte 40+ internationale Vue/React-Projekte (SaaS, E-Commerce) mit einer 100%igen Pünktlichkeitsrate und einer Bewertung von 5,0; verantwortete den vollständigen SDLC von der Kundenanfrage bis zur Produktion, einschließlich komplexer Drittanbieter-API-Integrationen.","proof_items.0.label":"Ausbildung","proof_items.0.value":"Informationssysteme","proof_items.0.note":"Suleyman Demirel University · 2018–2022 · GPA 3,72/4,0","proof_items.1.label":"Englisch","proof_items.1.value":"IELTS 7.0","proof_items.1.note":"Academic IELTS · CEFR-C1-Ergebnis","proof_items.2.label":"Auszeichnung","proof_items.2.value":"Silbermedaille","proof_items.2.note":"Infomatrix Asia-Pacific 2018 — internationaler Computerprojekt-Wettbewerb.","proof_items.3.label":"Empfehlung","proof_items.3.value":"KeyHorse","proof_items.3.note":"Unterschriebene Empfehlung der Unternehmensleitung","proof_items.4.label":"Sprachen","proof_items.4.value":"5 Sprachen","proof_items.4.note":"Englisch — verhandlungssicher · Kasachisch & Russisch — Muttersprache · Türkisch — Konversationsniveau · Chinesisch — Grundkenntnisse","proof_documents.ielts.title":"IELTS Academic 7.0/9.0","proof_documents.ielts.description":"Ergebnis des Academic IELTS (CEFR C1) — Nachweis fließenden, professionellen Englisch für internationale, remote-first Engineering-Rollen.","proof_documents.chinese-proficiency.title":"Chinesischkenntnisse","proof_documents.chinese-proficiency.description":"Grundkenntnisse in Chinesisch, entwickelt parallel zur beruflichen Arbeit mit grenzüberschreitenden Produkt- und Geschäftsteams.","proof_documents.infomatrix.title":"Silbermedaille — Infomatrix Asia-Pacific 2018","proof_documents.infomatrix.description":"Auszeichnung bei einem internationalen Computerprojekt-Wettbewerb für eine frühe technische Arbeit.","proof_documents.keyhorse.title":"Empfehlungsschreiben — KeyHorse","proof_documents.keyhorse.description":"Unterschriebene Empfehlung auf KeyHorse-Briefpapier, die Zhassulan für eine Senior-Engineering-Position empfiehlt.","projects.geonomix.description":"Groß angelegte Geodatenplattform und digitaler Zwilling, der interaktive Karten, kommunale Daten, digitale Register, öffentliche Dienstleistungen und Monitoring-Tools in regionalen Implementierungen vereint.","projects.midas-event.description":"Website einer Eventagentur, aufgebaut als durchstöberbares Portfolio vergangener Veranstaltungen statt als statische Leistungsliste, mit interaktiven Details in React.","projects.kostyum.description":"Responsives E-Commerce-Frontend für Herrenmode mit wiederverwendbarem Produktkatalog-UI und Fokus auf ein reibungsloses Einkaufserlebnis auf Desktop und Mobile.","projects.unistory.description":"Digitales Produktinterface, das Crypto-Wallet-Status und asynchrone Backend-Daten in wiederverwendbare React-Produktkomponenten integriert.","projects.kazmed.description":"Unternehmens-Frontend für einen autorisierten Servicepartner für medizinische Geräte, aufgebaut um einen Swiper-Katalog statt langer Textseiten.","projects.dostyk-trans-terminal.description":"Unternehmenswebsite eines Logistikterminals am Grenzübergang Dostyk–Alashankou, die Container-Umschlag-, Lager- und Transitdienste präsentiert.","projects.melissa.description":"Große Online-Apotheke mit über 13.000 Produkten, inklusive Katalog-Navigation, Suche, Filterung, Sortierung, Produktseiten, Warenkorb und Backend-Integrationen.","projects.abi-construction.description":"Website eines Bauunternehmens, die ein WordPress-CMS-Backend mit interaktiven Projektgalerien in Vue kombiniert.","projects.tahit.description":"Frontend eines Fertigungsunternehmens, das Textilproduktionskapazitäten, Technologie, Produkte und Dienstleistungen auf Desktop und Mobile präsentiert.","projects.dobraya.description":"Vitrine einer Online-Apotheke mit responsiven Katalogen, Kategorie-Navigation, Suche, Filterung und Checkout-Abläufen.","projects.asia-mebel.description":"Kommerzieller Katalog für Möbelmaterialien, Beschläge, Werkzeuge und Dienstleistungen mit strukturierter Navigation, Filterung, Suche und Produktseiten.","projects.pharmacom.description":"Website für ein Netzwerk von Impfkliniken und Apotheken, organisiert rund um Standorte, Dienstleistungen und Patienteninformationen statt einer einzigen statischen Startseite.","projects.navat.description":"Restaurant-Promo-Landingpage mit einem responsiven visuellen Erlebnis rund um Menü, Atmosphäre und Marke.","projects.asia-credit-bank.description":"Website des Kundenservice-Centers einer Bank, die eine große Anzahl von Produkt- und Support-Seiten in eine schnelle, leicht navigierbare Struktur verwandelt.","projects.geonomix.note":"Ein Produkt, bei dem die Karte im Mittelpunkt steht und Datenvolumen sowie wiederverwendbare regionale Auslieferung die Frontend-Architektur bestimmten.","projects.melissa.note":"Erfahrung mit einem großen Katalog, bei dem Informationsarchitektur genauso wichtig ist wie UI-Politur."},c={ru:r,kk:a,tr:l,zh:o,nl:m,de:d};function g(){const{locale:e}=s();function i(t,n){return c[e.value]?.[t]??n}return{tx:i}}export{g as u};
